const e={"es-first-u01.title":"Animali","es-first-u01.tip":"Guardate le figure, ascoltate e ripetete insieme. Non serve ancora saper leggere.","es-first-u01.w.0":"gatto","es-first-u01.w.1":"cane","es-first-u01.w.2":"pesce","es-first-u01.w.3":"uccello","es-first-u01.w.4":"mucca","es-first-u01.w.5":"maiale","es-first-u02.title":"Cibo","es-first-u02.tip":"Guardate le figure, ascoltate e ripetete insieme. Non serve ancora saper leggere.","es-first-u02.w.0":"mela","es-first-u02.w.1":"banana","es-first-u02.w.2":"latte","es-first-u02.w.3":"pane","es-first-u02.w.4":"uovo","es-first-u02.w.5":"torta","es-first-u03.title":"Giocattoli","es-first-u03.tip":"Guardate le figure, ascoltate e ripetete insieme. Non serve ancora saper leggere.","es-first-u03.w.0":"palla","es-first-u03.w.1":"macchina","es-first-u03.w.2":"orsacchiotto","es-first-u03.w.3":"aquilone","es-first-u03.w.4":"treno","es-first-u03.w.5":"barca","es-first-u04.title":"Il corpo","es-first-u04.tip":"Guardate le figure, ascoltate e ripetete insieme. Non serve ancora saper leggere.","es-first-u04.w.0":"occhio","es-first-u04.w.1":"orecchio","es-first-u04.w.2":"naso","es-first-u04.w.3":"bocca","es-first-u04.w.4":"mano","es-first-u04.w.5":"piede","es-first-u05.title":"Colori","es-first-u05.tip":"Guardate le figure, ascoltate e ripetete insieme. Non serve ancora saper leggere.","es-first-u05.w.0":"rosso","es-first-u05.w.1":"blu","es-first-u05.w.2":"giallo","es-first-u05.w.3":"verde","es-first-u05.w.4":"nero","es-first-u05.w.5":"bianco","es-first-u06.title":"Famiglia","es-first-u06.tip":"Guardate le figure, ascoltate e ripetete insieme. Non serve ancora saper leggere.","es-first-u06.w.0":"mamma","es-first-u06.w.1":"papà","es-first-u06.w.2":"bebè","es-first-u06.w.3":"bambino","es-first-u06.w.4":"bambina","es-first-u06.w.5":"nonna","es-first-u07.title":"A casa","es-first-u07.tip":"Guardate le figure, ascoltate e ripetete insieme. Non serve ancora saper leggere.","es-first-u07.w.0":"letto","es-first-u07.w.1":"sedia","es-first-u07.w.2":"porta","es-first-u07.w.3":"tazza","es-first-u07.w.4":"libro","es-first-u07.w.5":"orologio","es-first-u08.title":"Fuori","es-first-u08.tip":"Guardate le figure, ascoltate e ripetete insieme. Non serve ancora saper leggere.","es-first-u08.w.0":"sole","es-first-u08.w.1":"luna","es-first-u08.w.2":"stella","es-first-u08.w.3":"albero","es-first-u08.w.4":"fiore","es-first-u08.w.5":"pioggia"},a={"es-kinder-u01.title":"Le lettere A, B, C","es-kinder-u01.tip":'Ripeti i nomi delle lettere spagnole come una canzoncina: A si dice "a", B si dice "be", C si dice "se".',"es-kinder-u01.w.0":"albero","es-kinder-u01.w.1":"ape","es-kinder-u01.w.2":"acqua","es-kinder-u01.w.3":"bebè","es-kinder-u01.w.4":"barca","es-kinder-u01.w.5":"banana","es-kinder-u01.w.6":"casa","es-kinder-u01.w.7":"macchina","es-kinder-u01.s.0":"A come árbol (albero).","es-kinder-u01.s.1":"B come bebé (bebè).","es-kinder-u01.s.2":"C come casa (casa).","es-kinder-u02.title":"Le lettere D, E, F","es-kinder-u02.tip":'La E si legge "e". Cercate insieme in casa le cose che in spagnolo cominciano con D, E, F.',"es-kinder-u02.w.0":"dito","es-kinder-u02.w.1":"dado","es-kinder-u02.w.2":"delfino","es-kinder-u02.w.3":"elefante","es-kinder-u02.w.4":"stella","es-kinder-u02.w.5":"fiore","es-kinder-u02.w.6":"fragola","es-kinder-u02.w.7":"foto","es-kinder-u02.s.0":"D come dado (dado).","es-kinder-u02.s.1":"E come elefante (elefante).","es-kinder-u02.s.2":"F come flor (fiore).","es-kinder-u03.title":"Le lettere G, H, I","es-kinder-u03.tip":'In spagnolo la H è muta: huevo si legge "uevo".',"es-kinder-u03.w.0":"gatto","es-kinder-u03.w.1":"palloncino","es-kinder-u03.w.2":"gallina","es-kinder-u03.w.3":"gelato","es-kinder-u03.w.4":"uovo","es-kinder-u03.w.5":"foglia","es-kinder-u03.w.6":"isola","es-kinder-u03.w.7":"calamita","es-kinder-u03.s.0":"G come gato (gatto).","es-kinder-u03.s.1":"H come huevo (uovo).","es-kinder-u03.s.2":"I come isla (isola).","es-kinder-u04.title":"Le lettere J, K, L","es-kinder-u04.tip":'La J è un suono soffiato che viene dalla gola, come una "h" forte: jirafa suona come "hirafa".',"es-kinder-u04.w.0":"giraffa","es-kinder-u04.w.1":"succo","es-kinder-u04.w.2":"sapone","es-kinder-u04.w.3":"koala","es-kinder-u04.w.4":"kiwi","es-kinder-u04.w.5":"luna","es-kinder-u04.w.6":"leone","es-kinder-u04.w.7":"libro","es-kinder-u04.s.0":"J come jirafa (giraffa).","es-kinder-u04.s.1":"K come koala (koala).","es-kinder-u04.s.2":"L come luna (luna).","es-kinder-u05.title":"Le lettere M, N, Ñ","es-kinder-u05.tip":'La Ñ è una lettera che esiste solo in spagnolo. Suona come "gn" di gnomo: niño si dice "nigno"!',"es-kinder-u05.w.0":"mano","es-kinder-u05.w.1":"mela","es-kinder-u05.w.2":"scimmia","es-kinder-u05.w.3":"nuvola","es-kinder-u05.w.4":"naso","es-kinder-u05.w.5":"neve","es-kinder-u05.w.6":"bambino","es-kinder-u05.w.7":"gnu","es-kinder-u05.s.0":"M come mano (mano).","es-kinder-u05.s.1":"N come nube (nuvola).","es-kinder-u05.s.2":"Ñ come ñu (gnu).","es-kinder-u06.title":"Le lettere O, P, Q","es-kinder-u06.tip":`Dopo la Q c'è sempre una u e si legge "c" dura: queso si dice "cheso".`,"es-kinder-u06.w.0":"orso","es-kinder-u06.w.1":"occhio","es-kinder-u06.w.2":"pecora","es-kinder-u06.w.3":"pane","es-kinder-u06.w.4":"anatra","es-kinder-u06.w.5":"palla","es-kinder-u06.w.6":"pesce","es-kinder-u06.w.7":"formaggio","es-kinder-u06.s.0":"O come oso (orso).","es-kinder-u06.s.1":"P come pan (pane).","es-kinder-u06.s.2":"Q come queso (formaggio).","es-kinder-u07.title":"Le lettere R, S, T","es-kinder-u07.tip":'La R si fa vibrare con la lingua: "rrr". Se è difficile, per ora va bene anche una r leggera.',"es-kinder-u07.w.0":"topo","es-kinder-u07.w.1":"rana","es-kinder-u07.w.2":"sole","es-kinder-u07.w.3":"zuppa","es-kinder-u07.w.4":"sedia","es-kinder-u07.w.5":"treno","es-kinder-u07.w.6":"pomodoro","es-kinder-u07.w.7":"tartaruga","es-kinder-u07.s.0":"R come rana (rana).","es-kinder-u07.s.1":"S come sol (sole).","es-kinder-u07.s.2":"T come tren (treno).","es-kinder-u08.title":"Le lettere da U a Z","es-kinder-u08.tip":'La V si legge proprio come la B. La Z suona come una "s" leggera. Ora conosci tutte le lettere!',"es-kinder-u08.w.0":"uva","es-kinder-u08.w.1":"uno","es-kinder-u08.w.2":"mucca","es-kinder-u08.w.3":"bicchiere","es-kinder-u08.w.4":"yo-yo","es-kinder-u08.w.5":"yacht","es-kinder-u08.w.6":"scarpa","es-kinder-u08.w.7":"carota","es-kinder-u08.s.0":"U come uva (uva).","es-kinder-u08.s.1":"V come vaca (mucca).","es-kinder-u08.s.2":"Z come zapato (scarpa)."},s={"es-g12-u01.title":"Saluti","es-g12-u01.tip":"In spagnolo il punto esclamativo e il punto interrogativo si scrivono anche all'inizio della frase, al contrario (¡ ¿). Curioso, vero?","es-g12-u01.w.0":"ciao","es-g12-u01.w.1":"arrivederci","es-g12-u01.w.2":"grazie","es-g12-u01.w.3":"per favore","es-g12-u01.w.4":"sì","es-g12-u01.w.5":"no","es-g12-u01.w.6":"amico","es-g12-u01.w.7":"buongiorno","es-g12-u01.w.8":"buonanotte","es-g12-u01.s.0":"Ciao, amico!","es-g12-u01.s.1":"Buongiorno, mamma.","es-g12-u01.s.2":"Grazie, per favore.","es-g12-u01.s.3":"Sì, grazie.","es-g12-u01.s.4":"No, grazie.","es-g12-u01.s.5":"Buonanotte, arrivederci.","es-g12-u02.title":"I numeri da 1 a 10","es-g12-u02.tip":"Conta da uno a diez aprendo un dito alla volta.","es-g12-u02.w.0":"uno","es-g12-u02.w.1":"due","es-g12-u02.w.2":"tre","es-g12-u02.w.3":"quattro","es-g12-u02.w.4":"cinque","es-g12-u02.w.5":"sei","es-g12-u02.w.6":"sette","es-g12-u02.w.7":"otto","es-g12-u02.w.8":"nove","es-g12-u02.w.9":"dieci","es-g12-u02.s.0":"Uno, due, tre.","es-g12-u02.s.1":"Ho cinque anni.","es-g12-u02.s.2":"Quattro più quattro fa otto.","es-g12-u02.s.3":"Ho due mani.","es-g12-u02.s.4":"Dieci dita.","es-g12-u02.s.5":"Sei, sette, otto, nove, dieci.","es-g12-u03.title":"I colori","es-g12-u03.tip":'Il colore va dopo il nome: "manzana roja" (mela rossa). Con i nomi femminili la -o diventa -a.',"es-g12-u03.w.0":"rosso","es-g12-u03.w.1":"blu","es-g12-u03.w.2":"giallo","es-g12-u03.w.3":"verde","es-g12-u03.w.4":"bianco","es-g12-u03.w.5":"nero","es-g12-u03.w.6":"rosa","es-g12-u03.w.7":"arancione","es-g12-u03.w.8":"viola","es-g12-u03.s.0":"Il sole è giallo.","es-g12-u03.s.1":"La mela è rossa.","es-g12-u03.s.2":"Il mare è blu.","es-g12-u03.s.3":"Mi piace il verde.","es-g12-u03.s.4":"Il mio gatto è nero.","es-g12-u03.s.5":"Il fiore è rosa.","es-g12-u04.title":"La famiglia","es-g12-u04.tip":`mamá e papá si leggono con la forza sull'ultima sillaba: "mamÀ", "papÀ". L'accento (´) ti dice dove mettere la forza.`,"es-g12-u04.w.0":"mamma","es-g12-u04.w.1":"papà","es-g12-u04.w.2":"fratello","es-g12-u04.w.3":"sorella","es-g12-u04.w.4":"nonna","es-g12-u04.w.5":"nonno","es-g12-u04.w.6":"bebè","es-g12-u04.w.7":"famiglia","es-g12-u04.w.8":"cane","es-g12-u04.s.0":"Questa è la mia mamma.","es-g12-u04.s.1":"Il mio papà è alto.","es-g12-u04.s.2":"Ho una sorella.","es-g12-u04.s.3":"La mia nonna è buona.","es-g12-u04.s.4":"Il bebè dorme.","es-g12-u04.s.5":"La mia famiglia è grande.","es-g12-u05.title":"Gli animali","es-g12-u05.tip":"Davanti al nome di un animale metti el o la, come el gato, la vaca.","es-g12-u05.w.0":"gatto","es-g12-u05.w.1":"uccello","es-g12-u05.w.2":"pesce","es-g12-u05.w.3":"cavallo","es-g12-u05.w.4":"mucca","es-g12-u05.w.5":"maiale","es-g12-u05.w.6":"coniglio","es-g12-u05.w.7":"orso","es-g12-u05.w.8":"leone","es-g12-u05.s.0":"Il gatto è piccolo.","es-g12-u05.s.1":"Il leone è grande.","es-g12-u05.s.2":"La mucca mangia l'erba.","es-g12-u05.s.3":"L'uccello canta.","es-g12-u05.s.4":"Mi piace il coniglio.","es-g12-u05.s.5":"Il cavallo corre veloce.","es-g12-u06.title":"La frutta","es-g12-u06.tip":'"Me gusta" vuol dire "mi piace". Prova a dirlo con la tua frutta preferita.',"es-g12-u06.w.0":"mela","es-g12-u06.w.1":"banana","es-g12-u06.w.2":"fragola","es-g12-u06.w.3":"uva","es-g12-u06.w.4":"pera","es-g12-u06.w.5":"anguria","es-g12-u06.w.6":"limone","es-g12-u06.w.7":"pesca","es-g12-u06.w.8":"ciliegia","es-g12-u06.s.0":"Mi piace la fragola.","es-g12-u06.s.1":"L'anguria è grande.","es-g12-u06.s.2":"Voglio una mela.","es-g12-u06.s.3":"Il limone è giallo.","es-g12-u06.s.4":"L'uva è dolce.","es-g12-u06.s.5":"Una banana, per favore.","es-g12-u07.title":"Il cibo","es-g12-u07.tip":'como vuol dire "io mangio", bebo vuol dire "io bevo". Provali a tavola.',"es-g12-u07.w.0":"pane","es-g12-u07.w.1":"riso","es-g12-u07.w.2":"latte","es-g12-u07.w.3":"acqua","es-g12-u07.w.4":"formaggio","es-g12-u07.w.5":"uovo","es-g12-u07.w.6":"zuppa","es-g12-u07.w.7":"pollo","es-g12-u07.w.8":"pizza","es-g12-u07.s.0":"Voglio pane e formaggio.","es-g12-u07.s.1":"Bevo il latte.","es-g12-u07.s.2":"La zuppa è calda.","es-g12-u07.s.3":"Mangio riso con pollo.","es-g12-u07.s.4":"Acqua, per favore.","es-g12-u07.s.5":"Mi piace la pizza.","es-g12-u08.title":"Il corpo","es-g12-u08.tip":'"Me duele" vuol dire "mi fa male". Aggiungi la parte che fa male: Me duele la mano.',"es-g12-u08.w.0":"testa","es-g12-u08.w.1":"occhio","es-g12-u08.w.2":"naso","es-g12-u08.w.3":"bocca","es-g12-u08.w.4":"orecchio","es-g12-u08.w.5":"mano","es-g12-u08.w.6":"piede","es-g12-u08.w.7":"capelli","es-g12-u08.w.8":"dente","es-g12-u08.s.0":"Ho due occhi.","es-g12-u08.s.1":"I miei capelli sono neri.","es-g12-u08.s.2":"Tocca il naso.","es-g12-u08.s.3":"Mi fa male la testa.","es-g12-u08.s.4":"Mi lavo le mani.","es-g12-u08.s.5":"Apri la bocca.","es-g12-u09.title":"La scuola","es-g12-u09.tip":'"Voy a" vuol dire "io vado a". Voy a la escuela, voy a casa.',"es-g12-u09.w.0":"scuola","es-g12-u09.w.1":"libro","es-g12-u09.w.2":"matita","es-g12-u09.w.3":"zaino","es-g12-u09.w.4":"banco","es-g12-u09.w.5":"maestro","es-g12-u09.w.6":"foglio","es-g12-u09.w.7":"forbici","es-g12-u09.w.8":"lavagna","es-g12-u09.s.0":"Vado a scuola.","es-g12-u09.s.1":"Ho una matita.","es-g12-u09.s.2":"Il libro è sul banco.","es-g12-u09.s.3":"Il mio zaino è blu.","es-g12-u09.s.4":"Il maestro è buono.","es-g12-u09.s.5":"Dammi il foglio.","es-g12-u10.title":"La mia casa","es-g12-u10.tip":'"está en" vuol dire "è in / sta in". Prova a dire dove sono le cose.',"es-g12-u10.w.0":"casa","es-g12-u10.w.1":"porta","es-g12-u10.w.2":"finestra","es-g12-u10.w.3":"letto","es-g12-u10.w.4":"cucina","es-g12-u10.w.5":"bagno","es-g12-u10.w.6":"divano","es-g12-u10.w.7":"lampada","es-g12-u10.w.8":"giardino","es-g12-u10.s.0":"La mia casa è piccola.","es-g12-u10.s.1":"Apri la porta.","es-g12-u10.s.2":"Dormo nel mio letto.","es-g12-u10.s.3":"La mamma è in cucina.","es-g12-u10.s.4":"Il gatto è sul divano.","es-g12-u10.s.5":"Ci sono fiori in giardino.","es-g12-u11.title":"I vestiti","es-g12-u11.tip":'"Me pongo" vuol dire "mi metto". Prova a dirlo la mattina mentre ti vesti.',"es-g12-u11.w.0":"maglietta","es-g12-u11.w.1":"pantaloni","es-g12-u11.w.2":"scarpe","es-g12-u11.w.3":"berretto","es-g12-u11.w.4":"vestito","es-g12-u11.w.5":"cappotto","es-g12-u11.w.6":"calzini","es-g12-u11.w.7":"sciarpa","es-g12-u11.w.8":"guanti","es-g12-u11.s.0":"Mi metto la maglietta.","es-g12-u11.s.1":"Le mie scarpe sono rosse.","es-g12-u11.s.2":"Fa freddo, mettiti il cappotto.","es-g12-u11.s.3":"Mi piace questo vestito.","es-g12-u11.s.4":"Dov'è il mio berretto?","es-g12-u11.s.5":"I calzini sono blu.","es-g12-u12.title":"Il tempo","es-g12-u12.tip":"Il tempo si dice con hace: Hace sol (c'è il sole), Hace frío (fa freddo), Hace calor (fa caldo).","es-g12-u12.w.0":"sole","es-g12-u12.w.1":"pioggia","es-g12-u12.w.2":"neve","es-g12-u12.w.3":"vento","es-g12-u12.w.4":"nuvola","es-g12-u12.w.5":"caldo","es-g12-u12.w.6":"freddo","es-g12-u12.w.7":"ombrello","es-g12-u12.w.8":"arcobaleno","es-g12-u12.s.0":"C'è il sole.","es-g12-u12.s.1":"Oggi fa freddo.","es-g12-u12.s.2":"Piove tanto.","es-g12-u12.s.3":"C'è la neve in montagna.","es-g12-u12.s.4":"Fa molto caldo.","es-g12-u12.s.5":"Guarda l'arcobaleno.","es-g12-u13.title":"I giorni e la giornata","es-g12-u13.tip":'In spagnolo i giorni della settimana si scrivono con la lettera minuscola. mañana vuol dire sia "domani" sia "mattina".',"es-g12-u13.w.0":"lunedì","es-g12-u13.w.1":"martedì","es-g12-u13.w.2":"sabato","es-g12-u13.w.3":"domenica","es-g12-u13.w.4":"oggi","es-g12-u13.w.5":"domani","es-g12-u13.w.6":"notte","es-g12-u13.w.7":"pomeriggio","es-g12-u13.w.8":"settimana","es-g12-u13.s.0":"Oggi è lunedì.","es-g12-u13.s.1":"Domani è martedì.","es-g12-u13.s.2":"Il sabato non c'è scuola.","es-g12-u13.s.3":"Buon pomeriggio.","es-g12-u13.s.4":"Di notte dormo.","es-g12-u13.s.5":"La domenica gioco con papà.","es-g12-u14.title":"I mezzi di trasporto","es-g12-u14.tip":'"Voy en" vuol dire "vado in": voy en tren, voy en coche.',"es-g12-u14.w.0":"macchina","es-g12-u14.w.1":"autobus","es-g12-u14.w.2":"treno","es-g12-u14.w.3":"bicicletta","es-g12-u14.w.4":"aereo","es-g12-u14.w.5":"barca","es-g12-u14.w.6":"moto","es-g12-u14.w.7":"taxi","es-g12-u14.w.8":"camion","es-g12-u14.s.0":"Vado in autobus.","es-g12-u14.s.1":"Il treno è veloce.","es-g12-u14.s.2":"Ho una bicicletta rossa.","es-g12-u14.s.3":"L'aereo vola alto.","es-g12-u14.s.4":"La barca è in mare.","es-g12-u14.s.5":"Papà ha una macchina.","es-g12-u15.title":"Giochi e giocattoli","es-g12-u15.tip":'"Vamos a" vuol dire "andiamo a". Prova a dire a un amico: Vamos al parque!',"es-g12-u15.w.0":"palla","es-g12-u15.w.1":"bambola","es-g12-u15.w.2":"orsacchiotto","es-g12-u15.w.3":"macchinina","es-g12-u15.w.4":"puzzle","es-g12-u15.w.5":"aquilone","es-g12-u15.w.6":"palloncino","es-g12-u15.w.7":"gioco","es-g12-u15.w.8":"parco giochi","es-g12-u15.s.0":"Gioco con la palla.","es-g12-u15.s.1":"La mia bambola è bella.","es-g12-u15.s.2":"Andiamo al parco giochi.","es-g12-u15.s.3":"Il palloncino è rosso.","es-g12-u15.s.4":"Mi piace questo gioco.","es-g12-u15.s.5":"L'aquilone vola.","es-g12-u16.title":"La natura","es-g12-u16.tip":`"Veo" vuol dire "io vedo". Esci fuori e di' quello che vedi.`,"es-g12-u16.w.0":"albero","es-g12-u16.w.1":"fiore","es-g12-u16.w.2":"fiume","es-g12-u16.w.3":"montagna","es-g12-u16.w.4":"mare","es-g12-u16.w.5":"luna","es-g12-u16.w.6":"stella","es-g12-u16.w.7":"sasso","es-g12-u16.w.8":"erba","es-g12-u16.s.0":"L'albero è alto.","es-g12-u16.s.1":"La luna è bianca.","es-g12-u16.s.2":"Vedo una stella.","es-g12-u16.s.3":"Il fiume è lungo.","es-g12-u16.s.4":"Ci sono fiori in montagna.","es-g12-u16.s.5":"Mi piace il mare.","es-g12-u17.title":"Le emozioni","es-g12-u17.tip":"Come ti senti si dice con estoy: Estoy feliz. Se sei una bambina, le parole finiscono in -a: cansada, enfadada.","es-g12-u17.w.0":"felice","es-g12-u17.w.1":"triste","es-g12-u17.w.2":"arrabbiato","es-g12-u17.w.3":"stanco","es-g12-u17.w.4":"spaventato","es-g12-u17.w.5":"contento","es-g12-u17.w.6":"annoiato","es-g12-u17.w.7":"sorpreso","es-g12-u17.w.8":"malato","es-g12-u17.s.0":"Sono felice.","es-g12-u17.s.1":"Sei triste?","es-g12-u17.s.2":"Sono molto stanco.","es-g12-u17.s.3":"Mio fratello è arrabbiato.","es-g12-u17.s.4":"Non ho paura.","es-g12-u17.s.5":"Oggi sono malato.","es-g12-u18.title":"Le azioni","es-g12-u18.tip":'Le parole che finiscono in -ar, -er, -ir sono azioni. Puoi metterle così come sono dopo "Me gusta".',"es-g12-u18.w.0":"correre","es-g12-u18.w.1":"saltare","es-g12-u18.w.2":"mangiare","es-g12-u18.w.3":"bere","es-g12-u18.w.4":"dormire","es-g12-u18.w.5":"leggere","es-g12-u18.w.6":"cantare","es-g12-u18.w.7":"ballare","es-g12-u18.w.8":"nuotare","es-g12-u18.s.0":"Mi piace correre.","es-g12-u18.s.1":"Voglio mangiare.","es-g12-u18.s.2":"Andiamo a nuotare.","es-g12-u18.s.3":"Lei canta bene.","es-g12-u18.s.4":"Leggo un libro.","es-g12-u18.s.5":"Il cane salta.","es-g12-u19.title":"Il mio quartiere","es-g12-u19.tip":`"Hay" vuol dire "c'è". Mentre cammini per il quartiere prova a dire Hay una tienda, hay un parque.`,"es-g12-u19.w.0":"strada","es-g12-u19.w.1":"negozio","es-g12-u19.w.2":"parco","es-g12-u19.w.3":"ospedale","es-g12-u19.w.4":"biblioteca","es-g12-u19.w.5":"panetteria","es-g12-u19.w.6":"mercato","es-g12-u19.w.7":"chiesa","es-g12-u19.w.8":"semaforo","es-g12-u19.s.0":"Vivo in questa strada.","es-g12-u19.s.1":"Vado al negozio.","es-g12-u19.s.2":"La biblioteca è vicina.","es-g12-u19.s.3":"Compro il pane in panetteria.","es-g12-u19.s.4":"Il semaforo è rosso.","es-g12-u19.s.5":"Qui c'è un parco.","es-g12-u20.title":"La festa di compleanno","es-g12-u20.tip":'"¡Feliz cumpleaños!" vuol dire "Buon compleanno!". Dillo al compleanno di un amico.',"es-g12-u20.w.0":"compleanno","es-g12-u20.w.1":"regalo","es-g12-u20.w.2":"torta","es-g12-u20.w.3":"candelina","es-g12-u20.w.4":"festa","es-g12-u20.w.5":"canzone","es-g12-u20.w.6":"amici","es-g12-u20.w.7":"cappellino da festa","es-g12-u20.w.8":"gelato","es-g12-u20.s.0":"Buon compleanno!","es-g12-u20.s.1":"Oggi è la mia festa.","es-g12-u20.s.2":"Ho un regalo per te.","es-g12-u20.s.3":"Soffia sulle candeline.","es-g12-u20.s.4":"Cantiamo una canzone.","es-g12-u20.s.5":"I miei amici mangiano la torta."},o={"es-g34-u01.title":"Io sono: presentarsi","es-g34-u01.tip":'Lo spagnolo spesso lascia via il soggetto. Basta "Soy Lucía" per dire "Io sono Lucía".',"es-g34-u01.w.0":"studente","es-g34-u01.w.1":"maestra","es-g34-u01.w.2":"medico","es-g34-u01.w.3":"cuoco","es-g34-u01.w.4":"gentile","es-g34-u01.w.5":"alto","es-g34-u01.w.6":"basso","es-g34-u01.w.7":"intelligente","es-g34-u01.w.8":"nome","es-g34-u01.w.9":"paese (nazione)","es-g34-u01.s.0":"Io sono Lucía.","es-g34-u01.s.1":"Vengo dal Perù.","es-g34-u01.s.2":"Tu sei il mio amico.","es-g34-u01.s.3":"Lui è medico.","es-g34-u01.s.4":"Lei è molto intelligente.","es-g34-u01.s.5":"Noi siamo studenti.","es-g34-u01.s.6":"La mia maestra è gentile.","es-g34-u01.s.7":"Come ti chiami?","es-g34-u01.g.title":"Il verbo ser: soy, eres, es","es-g34-u01.g.x.0":'"Essere" si dice ser. Cambia forma a seconda della persona: yo soy, tú eres, él/ella es.',"es-g34-u01.g.x.1":"Al plurale: nosotros somos, ellos son.","es-g34-u01.g.x.2":"Usa ser per dire nome, lavoro, paese e carattere. Soy estudiante. Es de México.","es-g34-u01.g.0":"Io sono uno studente.","es-g34-u01.g.1":"Tu sei alto.","es-g34-u01.g.2":"Lei è una maestra.","es-g34-u01.g.3":"Noi siamo amici.","es-g34-u01.g.4":"Loro vengono dalla Spagna.","es-g34-u01.g.5":"Tu sei il mio amico.","es-g34-u01.g.5.task":'Riscrivi la frase iniziando con "Tú"',"es-g34-u01.g.6":"Lei è intelligente.","es-g34-u01.g.6.task":'Riscrivi la frase iniziando con "Ella"',"es-g34-u01.g.7":"Noi siamo studenti.","es-g34-u01.g.7.task":'Riscrivi la frase iniziando con "Nosotros"',"es-g34-u01.st.title":"Un nuovo amico","es-g34-u01.st.l.0":"Ciao! Io sono Lucía. Come ti chiami?","es-g34-u01.st.l.1":"Io sono Mateo. Vengo dal Messico.","es-g34-u01.st.l.2":"Io vengo dal Perù. Sono una studentessa.","es-g34-u01.st.l.3":"Anch'io. Mia mamma è medico.","es-g34-u01.st.l.4":"Che bello! Mio papà è cuoco.","es-g34-u01.st.l.5":"Sei davvero gentile, Lucía.","es-g34-u01.st.q.0":"Da dove viene Mateo?","es-g34-u01.st.q.0.o.0":"Dal Messico","es-g34-u01.st.q.0.o.1":"Dal Perù","es-g34-u01.st.q.0.o.2":"Dalla Spagna","es-g34-u01.st.q.1":"Che lavoro fa il papà di Lucía?","es-g34-u01.st.q.1.o.0":"Medico","es-g34-u01.st.q.1.o.1":"Cuoco","es-g34-u01.st.q.1.o.2":"Maestro","es-g34-u02.title":"Dove sei? Come stai?","es-g34-u02.tip":"Per come ti senti si usa estar! Estoy feliz, estoy cansado. Se sei una bambina, finisce in -a: contenta, nerviosa.","es-g34-u02.w.0":"qui","es-g34-u02.w.1":"lì","es-g34-u02.w.2":"vicino","es-g34-u02.w.3":"lontano","es-g34-u02.w.4":"contento","es-g34-u02.w.5":"nervoso","es-g34-u02.w.6":"occupato","es-g34-u02.w.7":"pronto","es-g34-u02.w.8":"sopra","es-g34-u02.w.9":"sotto","es-g34-u02.s.0":"Sono a casa.","es-g34-u02.s.1":"Dove sei?","es-g34-u02.s.2":"Il libro è sopra il banco.","es-g34-u02.s.3":"La mamma è occupata.","es-g34-u02.s.4":"Siamo molto contenti.","es-g34-u02.s.5":"La scuola è vicina.","es-g34-u02.s.6":"Sono un po' nervoso.","es-g34-u02.s.7":"Sei pronto?","es-g34-u02.g.title":"Il verbo estar: luogo e stato d'animo","es-g34-u02.g.x.0":"Per dire dove sei e come ti senti adesso si usa estar: estoy, estás, está, estamos, están.","es-g34-u02.g.x.1":"Estoy en casa. (Sono a casa) / Está contento. (Lui è contento)","es-g34-u02.g.x.2":`ser è per "com'è di solito", estar è per "come sta adesso e dove si trova".`,"es-g34-u02.g.0":"Sono a scuola.","es-g34-u02.g.1":"Sei contento?","es-g34-u02.g.2":"Il gatto è sotto la sedia.","es-g34-u02.g.3":"Siamo pronti.","es-g34-u02.g.4":"Loro sono lontani.","es-g34-u02.g.5":"Lei è nervosa.","es-g34-u02.g.5.task":'Riscrivi la frase iniziando con "Ella"',"es-g34-u02.g.6":"Dove sei?","es-g34-u02.g.6.task":'Trasformala in una domanda con "¿Dónde…?"',"es-g34-u02.g.7":"Siamo a casa.","es-g34-u02.g.7.task":'Riscrivi la frase iniziando con "Nosotros"',"es-g34-u03.title":"el e la: il genere delle parole","es-g34-u03.tip":'Quando impari una parola nuova, impara anche el/la insieme. Non "mesa" ma "la mesa"!',"es-g34-u03.w.0":"bambino","es-g34-u03.w.1":"bambina","es-g34-u03.w.2":"ragazzo","es-g34-u03.w.3":"ragazza","es-g34-u03.w.4":"quaderno","es-g34-u03.w.5":"finestra","es-g34-u03.w.6":"paese (villaggio)","es-g34-u03.w.7":"città","es-g34-u03.w.8":"mano","es-g34-u03.w.9":"problema","es-g34-u03.s.0":"Il bambino ha un quaderno.","es-g34-u03.s.1":"La bambina apre la finestra.","es-g34-u03.s.2":"I ragazzi giocano a calcio.","es-g34-u03.s.3":"Le ragazze cantano.","es-g34-u03.s.4":"La città è molto grande.","es-g34-u03.s.5":"Il paese è piccolo e carino.","es-g34-u03.s.6":"La mano ha cinque dita.","es-g34-u03.s.7":"Il problema è difficile.","es-g34-u03.g.title":"Gli articoli el / la / los / las","es-g34-u03.g.x.0":"I nomi spagnoli sono maschili o femminili. Di solito se finiscono in -o sono maschili (el niño), se finiscono in -a sono femminili (la niña).","es-g34-u03.g.x.1":"Al plurale si usano los, las: los niños, las niñas.","es-g34-u03.g.x.2":"Ci sono eccezioni: la mano (femminile), el problema (maschile). Impara la parola insieme al suo articolo.","es-g34-u03.g.0":"Il bambino mangia il pane.","es-g34-u03.g.1":"La bambina ha un gatto.","es-g34-u03.g.2":"I ragazzi sono al parco.","es-g34-u03.g.3":"Le finestre sono aperte.","es-g34-u03.g.3.task":"Metti al plurale","es-g34-u03.g.4":"La mano è piccola.","es-g34-u03.g.5":"Il problema è facile.","es-g34-u03.g.6":"I bambini giocano.","es-g34-u03.g.6.task":"Metti al plurale","es-g34-u03.g.7":"Le ragazze cantano.","es-g34-u03.g.7.task":"Metti al plurale","es-g34-u03.st.title":"In classe","es-g34-u03.st.l.0":"Buongiorno, bambini. Aprite il quaderno.","es-g34-u03.st.l.1":"Maestra, non ho il mio quaderno.","es-g34-u03.st.l.2":"Dov'è il tuo quaderno, Diego?","es-g34-u03.st.l.3":"A casa, sul tavolo.","es-g34-u03.st.l.4":"Io ho due quaderni. Prendine uno.","es-g34-u03.st.l.5":"Grazie, Ana! Sei davvero gentile.","es-g34-u03.st.q.0":"Dov'è il quaderno di Diego?","es-g34-u03.st.q.0.o.0":"A scuola","es-g34-u03.st.q.0.o.1":"Sul tavolo di casa","es-g34-u03.st.q.0.o.2":"Nello zaino","es-g34-u03.st.q.1":"Chi presta il quaderno?","es-g34-u03.st.q.1.o.0":"La maestra","es-g34-u03.st.q.1.o.1":"Diego","es-g34-u03.st.q.1.o.2":"Ana","es-g34-u04.title":"Mela rossa, mele rosse: gli aggettivi","es-g34-u04.tip":"Se il nome finisce in -a, anche l'aggettivo finisce in -a; se il nome è plurale, anche l'aggettivo prende la -s. Pensa che devono fare coppia.","es-g34-u04.w.0":"grande","es-g34-u04.w.1":"piccolo","es-g34-u04.w.2":"bello","es-g34-u04.w.3":"brutto","es-g34-u04.w.4":"nuovo","es-g34-u04.w.5":"vecchio","es-g34-u04.w.6":"veloce","es-g34-u04.w.7":"lento","es-g34-u04.w.8":"pulito","es-g34-u04.w.9":"sporco","es-g34-u04.s.0":"La mela è rossa.","es-g34-u04.s.1":"Le mele sono rosse.","es-g34-u04.s.2":"La macchina nuova è veloce.","es-g34-u04.s.3":"La mia casa è piccola e bella.","es-g34-u04.s.4":"I libri vecchi sono sporchi.","es-g34-u04.s.5":"La tartaruga è lenta.","es-g34-u04.s.6":"Le mie scarpe sono pulite.","es-g34-u04.s.7":"Il cane grande è brutto.","es-g34-u04.g.title":"Accordo dell'aggettivo: -o/-a, -os/-as","es-g34-u04.g.x.0":"L'aggettivo cambia forma per accordarsi con il nome: el niño alto, la niña alta.","es-g34-u04.g.x.1":"Al plurale si aggiunge -s: los niños altos, las niñas altas.","es-g34-u04.g.x.2":"Gli aggettivi in -e come grande, inteligente sono uguali per maschile e femminile: el niño grande, la niña grande.","es-g34-u04.g.x.3":"Di solito l'aggettivo va dopo il nome: la casa bonita.","es-g34-u04.g.0":"La casa è bella.","es-g34-u04.g.1":"La macchina è nuova.","es-g34-u04.g.2":"I cani sono veloci.","es-g34-u04.g.3":"Le bambine sono intelligenti.","es-g34-u04.g.4":"La tartaruga è lenta.","es-g34-u04.g.5":"Le mele sono rosse.","es-g34-u04.g.5.task":"Metti al plurale","es-g34-u04.g.6":"Lo zaino è nuovo.","es-g34-u04.g.6.task":'Riscrivila con "La mochila"',"es-g34-u04.g.7":"I gatti sono piccoli.","es-g34-u04.g.7.task":"Metti al plurale","es-g34-u05.title":"I verbi in -ar: hablo, hablas, habla","es-g34-u05.tip":"-o (io), -as (tu), -a (lui/lei), -amos (noi), -an (loro). Basta guardare la finale per capire chi fa l'azione!","es-g34-u05.w.0":"parlare","es-g34-u05.w.1":"studiare","es-g34-u05.w.2":"ascoltare","es-g34-u05.w.3":"camminare","es-g34-u05.w.4":"cucinare","es-g34-u05.w.5":"disegnare","es-g34-u05.w.6":"lavorare","es-g34-u05.w.7":"nuotare","es-g34-u05.w.8":"musica","es-g34-u05.w.9":"piscina","es-g34-u05.s.0":"Io parlo spagnolo.","es-g34-u05.s.1":"Tu studi molto.","es-g34-u05.s.2":"Lei ascolta la musica.","es-g34-u05.s.3":"Noi camminiamo fino al parco.","es-g34-u05.s.4":"Mio papà cucina la cena.","es-g34-u05.s.5":"I bambini disegnano animali.","es-g34-u05.s.6":"La mamma lavora il lunedì.","es-g34-u05.s.7":"Nuotiamo in piscina.","es-g34-u05.g.title":"Presente dei verbi regolari in -ar","es-g34-u05.g.x.0":"Nei verbi in -ar togli -ar e aggiungi la finale della persona: habl-o, habl-as, habl-a, habl-amos, habl-an.","es-g34-u05.g.x.1":"yo hablo (io parlo), tú hablas (tu), él/ella habla (lui/lei), nosotros hablamos (noi), ellos hablan (loro).","es-g34-u05.g.x.2":"Anche estudiar, caminar, cocinar cambiano allo stesso modo.","es-g34-u05.g.0":"Io parlo con la nonna.","es-g34-u05.g.1":"Tu cammini veloce.","es-g34-u05.g.2":"Lei disegna molto bene.","es-g34-u05.g.3":"Noi nuotiamo ogni sabato.","es-g34-u05.g.4":"Loro ascoltano la maestra.","es-g34-u05.g.5":"Lei studia inglese.","es-g34-u05.g.5.task":'Riscrivi la frase iniziando con "Ella"',"es-g34-u05.g.6":"Noi lavoriamo a casa.","es-g34-u05.g.6.task":'Riscrivi la frase iniziando con "Nosotros"',"es-g34-u05.g.7":"Tu cucini la cena.","es-g34-u05.g.7.task":'Riscrivi la frase iniziando con "Tú"',"es-g34-u06.title":"I verbi in -er e -ir: como, vivo","es-g34-u06.tip":'-er e -ir sono quasi uguali. Cambiano solo con "noi": comemos / vivimos.',"es-g34-u06.w.0":"mangiare","es-g34-u06.w.1":"bere","es-g34-u06.w.2":"leggere","es-g34-u06.w.3":"imparare","es-g34-u06.w.4":"correre","es-g34-u06.w.5":"vivere","es-g34-u06.w.6":"scrivere","es-g34-u06.w.7":"aprire","es-g34-u06.w.8":"lettera","es-g34-u06.w.9":"storia (racconto)","es-g34-u06.s.0":"Io mangio il riso.","es-g34-u06.s.1":"Tu bevi il latte.","es-g34-u06.s.2":"Lei legge una storia.","es-g34-u06.s.3":"Noi impariamo lo spagnolo.","es-g34-u06.s.4":"Io vivo a Lima.","es-g34-u06.s.5":"Lui scrive una lettera.","es-g34-u06.s.6":"I bambini corrono veloci.","es-g34-u06.s.7":"Noi apriamo la finestra.","es-g34-u06.g.title":"Presente dei verbi regolari in -er / -ir","es-g34-u06.g.x.0":"Verbi in -er: com-o, com-es, com-e, com-emos, com-en.","es-g34-u06.g.x.1":'Verbi in -ir: viv-o, viv-es, viv-e, viv-imos, viv-en. Solo "noi" cambia, con -imos.',"es-g34-u06.g.x.2":"Confronta con -ar: tú hablas / tú comes / tú vives. Ricorda: la a diventa e.","es-g34-u06.g.0":"Io mangio il pane.","es-g34-u06.g.1":"Tu leggi molti libri.","es-g34-u06.g.2":"Lei vive a Madrid.","es-g34-u06.g.3":"Noi viviamo qui.","es-g34-u06.g.4":"Loro bevono acqua.","es-g34-u06.g.5":"Noi mangiamo insieme.","es-g34-u06.g.5.task":'Riscrivila con "Nosotros … juntos"',"es-g34-u06.g.6":"Lei scrive una lettera.","es-g34-u06.g.6.task":'Riscrivi la frase iniziando con "Ella"',"es-g34-u06.g.7":"Tu apri la porta.","es-g34-u06.g.7.task":'Riscrivi la frase iniziando con "Tú"',"es-g34-u07.title":"Mi piace: gustar","es-g34-u07.tip":'gusta/gustan si accorda con "la cosa che piace", non con "io". Se le cose sono tante, gustan!',"es-g34-u07.w.0":"cioccolato","es-g34-u07.w.1":"calcio","es-g34-u07.w.2":"film","es-g34-u07.w.3":"sport","es-g34-u07.w.4":"verdure","es-g34-u07.w.5":"dolce (dessert)","es-g34-u07.w.6":"compiti","es-g34-u07.w.7":"preferito","es-g34-u07.w.8":"ballare","es-g34-u07.w.9":"cantare","es-g34-u07.s.0":"Mi piace il cioccolato.","es-g34-u07.s.1":"Mi piacciono gli sport.","es-g34-u07.s.2":"Ti piace il calcio?","es-g34-u07.s.3":"Non mi piacciono le verdure.","es-g34-u07.s.4":"A Mateo piace ballare.","es-g34-u07.s.5":"Il mio dolce preferito è il gelato.","es-g34-u07.s.6":"Ci piace guardare i film.","es-g34-u07.s.7":"Non mi piacciono i compiti.","es-g34-u07.g.title":"gustar: me gusta / me gustan","es-g34-u07.g.x.0":'"Mi piace" si dice me gusta. Se la cosa che piace è una sola, gusta; se sono tante, gustan.',"es-g34-u07.g.x.1":"Me gusta el helado. / Me gustan las fresas.","es-g34-u07.g.x.2":"A te: te gusta, a lui/lei: le gusta, a noi: nos gusta. Con un nome di persona: A Ana le gusta…","es-g34-u07.g.x.3":"Se piace un'azione, sempre gusta: Me gusta bailar.","es-g34-u07.g.0":"Mi piace il cioccolato.","es-g34-u07.g.1":"Mi piacciono i film.","es-g34-u07.g.2":"Ti piace il calcio?","es-g34-u07.g.3":"A Lucía piace cantare.","es-g34-u07.g.4":"Ci piace la musica.","es-g34-u07.g.5":"Mi piacciono gli sport.","es-g34-u07.g.5.task":'Riscrivila con "los deportes" (plurale)',"es-g34-u07.g.6":"Non mi piacciono i compiti.","es-g34-u07.g.6.task":"Trasformala in una frase negativa (no)","es-g34-u07.g.7":"Ti piacciono le verdure?","es-g34-u07.g.7.task":'Trasformala in una domanda con "¿Te…?"',"es-g34-u07.st.title":"L'ora della merenda","es-g34-u07.st.l.0":"Hugo, ti piace il cioccolato?","es-g34-u07.st.l.1":"Sì! Mi piace tantissimo. E a te?","es-g34-u07.st.l.2":"A me piacciono le fragole. Sono il mio dolce preferito.","es-g34-u07.st.l.3":"Ti piacciono le verdure?","es-g34-u07.st.l.4":"No, non mi piacciono. Però mi piace la zuppa.","es-g34-u07.st.l.5":"Alla mia mamma piace fare la zuppa. Andiamo a casa mia!","es-g34-u07.st.q.0":"Qual è il dolce preferito di Sofía?","es-g34-u07.st.q.0.o.0":"Il cioccolato","es-g34-u07.st.q.0.o.1":"Le fragole","es-g34-u07.st.q.0.o.2":"La zuppa","es-g34-u07.st.q.1":"Che cosa non piace a Sofía?","es-g34-u07.st.q.1.o.0":"La zuppa","es-g34-u07.st.q.1.o.1":"Le fragole","es-g34-u07.st.q.1.o.2":"Le verdure","es-g34-u08.title":"Mio, tuo: mi, tu, su","es-g34-u08.tip":`tu (tuo) non ha l'accento, tú (tu) sì. "tú tienes tu libro": tu hai il tuo libro.`,"es-g34-u08.w.0":"giocattolo","es-g34-u08.w.1":"bicicletta","es-g34-u08.w.2":"animale domestico","es-g34-u08.w.3":"vicino di casa","es-g34-u08.w.4":"cugino","es-g34-u08.w.5":"zio","es-g34-u08.w.6":"zia","es-g34-u08.w.7":"camera","es-g34-u08.w.8":"telefono","es-g34-u08.w.9":"soldi","es-g34-u08.s.0":"Il mio animale domestico è un cane.","es-g34-u08.s.1":"La tua bicicletta è nuova.","es-g34-u08.s.2":"La sua camera è grande.","es-g34-u08.s.3":"La nostra casa è vicina.","es-g34-u08.s.4":"I miei cugini vivono in Cile.","es-g34-u08.s.5":"Dov'è il tuo telefono?","es-g34-u08.s.6":"Nostra zia ha due gatti.","es-g34-u08.s.7":"I suoi giocattoli sono nella scatola.","es-g34-u08.g.title":"Possessivi mi / tu / su / nuestro","es-g34-u08.g.x.0":"mio = mi, tuo = tu, suo = su, nostro = nuestro/nuestra.","es-g34-u08.g.x.1":"Se la cosa posseduta è plurale, aggiungi -s: mis libros, tus zapatos, sus gatos.","es-g34-u08.g.x.2":"Solo nuestro cambia al femminile: nuestro perro, nuestra casa.","es-g34-u08.g.0":"Il mio animale domestico è un gatto.","es-g34-u08.g.1":"Le tue scarpe sono nuove.","es-g34-u08.g.2":"Suo cugino vive in Messico.","es-g34-u08.g.3":"La nostra casa è bella.","es-g34-u08.g.4":"I nostri vicini sono gentili.","es-g34-u08.g.5":"I miei giocattoli sono qui.","es-g34-u08.g.5.task":"Metti al plurale","es-g34-u08.g.6":"Il tuo telefono è nuovo.","es-g34-u08.g.6.task":'Riscrivila con "Tu" (tuo)',"es-g34-u08.g.7":"Sua zia vive vicino.","es-g34-u08.g.7.task":'Riscrivila con "Su" (suo)',"es-g34-u09.title":"Cosa? Chi? Dove?: fare domande","es-g34-u09.tip":"Nelle domande metti sempre il punto interrogativo rovesciato ¿ all'inizio. Leggendo, alza la voce alla fine.","es-g34-u09.w.0":"che cosa","es-g34-u09.w.1":"chi","es-g34-u09.w.2":"dove","es-g34-u09.w.3":"quando","es-g34-u09.w.4":"come","es-g34-u09.w.5":"quanto","es-g34-u09.w.6":"perché","es-g34-u09.w.7":"risposta","es-g34-u09.w.8":"domanda","es-g34-u09.w.9":"costare","es-g34-u09.s.0":"Che cos'è questo?","es-g34-u09.s.1":"Chi è lei?","es-g34-u09.s.2":"Dove vivi?","es-g34-u09.s.3":"Quando è la festa?","es-g34-u09.s.4":"Come ti chiami?","es-g34-u09.s.5":"Quanto costa il libro?","es-g34-u09.s.6":"Perché piangi?","es-g34-u09.s.7":"Ho una domanda.","es-g34-u09.g.title":"Gli interrogativi: qué, quién, dónde, cuándo, cómo, cuánto","es-g34-u09.g.x.0":"Le parole per fare domande hanno tutte l'accento: qué (che cosa), quién (chi), dónde (dove), cuándo (quando), cómo (come), cuánto (quanto).","es-g34-u09.g.x.1":"La domanda comincia con ¿ e finisce con ?: ¿Dónde está el gato?","es-g34-u09.g.x.2":"Di solito il verbo viene subito dopo la parola interrogativa: ¿Qué comes? ¿Quién canta?","es-g34-u09.g.0":"Che cosa mangi?","es-g34-u09.g.1":"Chi è il tuo amico?","es-g34-u09.g.2":"Dov'è il mio zaino?","es-g34-u09.g.3":"Quand'è il tuo compleanno?","es-g34-u09.g.4":"Come stai?","es-g34-u09.g.4.task":'Trasformala in una domanda con "¿Cómo…?"',"es-g34-u09.g.5":"Quanto costa?","es-g34-u09.g.6":"Dove vive Lucía?","es-g34-u09.g.6.task":'Trasformala in una domanda con "¿Dónde…?"',"es-g34-u09.g.7":"Che cosa legge Mateo?","es-g34-u09.g.7.task":'Trasformala in una domanda con "¿Qué…?"',"es-g34-u10.title":"No, non lo faccio: la frase negativa","es-g34-u10.tip":'In spagnolo si può dire "No … nada", con due negazioni, ed è giusto. Proprio come in italiano!',"es-g34-u10.w.0":"niente","es-g34-u10.w.1":"mai","es-g34-u10.w.2":"nessuno","es-g34-u10.w.3":"sempre","es-g34-u10.w.4":"anche","es-g34-u10.w.5":"neanche","es-g34-u10.w.6":"ancora (non ancora)","es-g34-u10.w.7":"già","es-g34-u10.w.8":"bugia","es-g34-u10.w.9":"verità","es-g34-u10.s.0":"Non ho fame.","es-g34-u10.s.1":"Non mi piace il freddo.","es-g34-u10.s.2":"Non voglio niente.","es-g34-u10.s.3":"Non arrivo mai in ritardo.","es-g34-u10.s.4":"Qui non c'è nessuno.","es-g34-u10.s.5":"Neanch'io vado.","es-g34-u10.s.6":"Non so ancora leggere.","es-g34-u10.s.7":"Non è vero.","es-g34-u10.g.title":"La negazione: no + verbo, nada, nunca, nadie","es-g34-u10.g.x.0":'Per dire "non…" metti no davanti al verbo: No como. No tengo gato.',"es-g34-u10.g.x.1":"Se nada (niente), nadie (nessuno), nunca (mai) vengono dopo il verbo, si usa anche no: No veo nada.","es-g34-u10.g.x.2":`"Anch'io" è también, "neanch'io" è tampoco.`,"es-g34-u10.g.0":"Non ho fame.","es-g34-u10.g.1":"Non vedo niente.","es-g34-u10.g.2":"Non c'è nessuno a casa.","es-g34-u10.g.3":"Non mangio mai caramelle.","es-g34-u10.g.4":"Neanch'io lo voglio.","es-g34-u10.g.5":"Non mi piace la pioggia.","es-g34-u10.g.5.task":"Trasformala in una frase negativa (no)","es-g34-u10.g.6":"Lei non mangia carne.","es-g34-u10.g.6.task":"Trasformala in una frase negativa (no)","es-g34-u10.g.7":"Non voglio niente.","es-g34-u10.g.7.task":'Trasformala in una frase negativa con "nada"',"es-g34-u11.title":"C'è: hay","es-g34-u11.tip":`hay vuol dire "c'è", está vuol dire "si trova (in un posto)". Hay un gato (c'è un gatto) / El gato está aquí (il gatto è qui).`,"es-g34-u11.w.0":"mercato","es-g34-u11.w.1":"negozio","es-g34-u11.w.2":"pane","es-g34-u11.w.3":"uova","es-g34-u11.w.4":"frutta","es-g34-u11.w.5":"latte","es-g34-u11.w.6":"sacchetto (borsa)","es-g34-u11.w.7":"frigorifero","es-g34-u11.w.8":"molto","es-g34-u11.w.9":"poco","es-g34-u11.s.0":"C'è un gatto in giardino.","es-g34-u11.s.1":"Al mercato c'è molta frutta.","es-g34-u11.s.2":"Non c'è latte nel frigorifero.","es-g34-u11.s.3":"C'è del pane?","es-g34-u11.s.4":"Nel sacchetto ci sono sei uova.","es-g34-u11.s.5":"C'è poca acqua.","es-g34-u11.s.6":"Nella mia classe ci sono venti bambini.","es-g34-u11.s.7":"Qui vicino c'è un negozio.","es-g34-u11.g.title":"hay: c'è / non c'è","es-g34-u11.g.x.0":`"C'è" e "ci sono" si dicono tutti e due hay. La forma non cambia: Hay un gato. Hay tres gatos.`,"es-g34-u11.g.x.1":"Se non c'è, No hay: No hay leche.","es-g34-u11.g.x.2":"Per dire quanto, mucho/mucha (molto) e poco/poca (poco) si accordano con il nome: mucha fruta, pocos huevos.","es-g34-u11.g.0":"C'è un cane in strada.","es-g34-u11.g.1":"Qui ci sono molti negozi.","es-g34-u11.g.2":"Non c'è pane.","es-g34-u11.g.3":"C'è molta frutta.","es-g34-u11.g.4":"Ci sono poche uova.","es-g34-u11.g.5":"Non c'è latte a casa.","es-g34-u11.g.5.task":"Trasformala in una frase negativa (no)","es-g34-u11.g.6":"C'è un frigorifero qui?","es-g34-u11.g.6.task":"Trasformala in una domanda","es-g34-u11.g.7":"Al parco ci sono molti bambini.","es-g34-u11.g.7.task":'Riscrivila con "muchos" (molti)',"es-g34-u12.title":"Ho fame, ho sete: le espressioni con tener","es-g34-u12.tip":`Per chiedere l'età si dice "¿Cuántos años tienes?" (quanti anni hai?). La risposta è "Tengo … años."`,"es-g34-u12.w.0":"fame","es-g34-u12.w.1":"sete","es-g34-u12.w.2":"sonno","es-g34-u12.w.3":"paura","es-g34-u12.w.4":"fretta","es-g34-u12.w.5":"fortuna","es-g34-u12.w.6":"ragione","es-g34-u12.w.7":"anni (età)","es-g34-u12.w.8":"panino","es-g34-u12.w.9":"coperta","es-g34-u12.s.0":"Ho fame.","es-g34-u12.s.1":"Hai sete?","es-g34-u12.s.2":"Ho nove anni.","es-g34-u12.s.3":"La mia sorellina ha sonno.","es-g34-u12.s.4":"Abbiamo fretta.","es-g34-u12.s.5":"Non ho paura.","es-g34-u12.s.6":"Hai ragione.","es-g34-u12.s.7":"Ho freddo, mi serve una coperta.","es-g34-u12.g.title":"Espressioni con tener: tengo hambre, tengo años","es-g34-u12.g.x.0":`tener vuol dire "avere", e in spagnolo si "ha" anche la fame, la sete e l'età: Tengo hambre. Tengo diez años.`,"es-g34-u12.g.x.1":"tengo, tienes, tiene, tenemos, tienen. Solo yo è speciale: tengo.","es-g34-u12.g.x.2":"tener frío (avere freddo), tener calor (avere caldo), tener sueño (avere sonno), tener miedo (avere paura), tener prisa (avere fretta), tener razón (avere ragione).","es-g34-u12.g.0":"Ho fame.","es-g34-u12.g.1":"Hai sete?","es-g34-u12.g.2":"Lei ha otto anni.","es-g34-u12.g.3":"Abbiamo fretta.","es-g34-u12.g.4":"Loro hanno paura.","es-g34-u12.g.5":"Mio nonno ha settant'anni.","es-g34-u12.g.5.task":'Riscrivila con "Mi abuelo … setenta"',"es-g34-u12.g.6":"Non ho sonno.","es-g34-u12.g.6.task":"Trasformala in una frase negativa (no)","es-g34-u12.g.7":"Hai freddo?","es-g34-u12.g.7.task":'Trasformala in una domanda con "¿Tú…?"',"es-g34-u12.st.title":"La ricreazione","es-g34-u12.st.l.0":"Ho tanta fame. Hai un panino?","es-g34-u12.st.l.1":"Sì, ne ho due. Prendine uno.","es-g34-u12.st.l.2":"Grazie! Ho anche sete.","es-g34-u12.st.l.3":"C'è acqua alla fontanella. Quanti anni hai, Pablo?","es-g34-u12.st.l.4":"Nove. E tu?","es-g34-u12.st.l.5":"Io ne ho dieci. Sbrighiamoci, la lezione comincia tra poco!","es-g34-u12.st.q.0":"Che cosa vuole Pablo?","es-g34-u12.st.q.0.o.0":"Un libro","es-g34-u12.st.q.0.o.1":"Un panino e dell'acqua","es-g34-u12.st.q.0.o.2":"Una palla","es-g34-u12.st.q.1":"Quanti anni ha Marta?","es-g34-u12.st.q.1.o.0":"Nove anni","es-g34-u12.st.q.1.o.1":"Dieci anni","es-g34-u12.st.q.1.o.2":"Otto anni","es-g34-u13.title":"ser o estar?","es-g34-u13.tip":'Se hai dubbi, chiediti: "È così di solito?" → ser. "È così adesso? Dove si trova?" → estar.',"es-g34-u13.w.0":"noioso","es-g34-u13.w.1":"divertente","es-g34-u13.w.2":"malato","es-g34-u13.w.3":"sano","es-g34-u13.w.4":"aperto","es-g34-u13.w.5":"chiuso","es-g34-u13.w.6":"caldo (bollente)","es-g34-u13.w.7":"freddo","es-g34-u13.w.8":"giovane","es-g34-u13.w.9":"gentile","es-g34-u13.s.0":"Il mio maestro è giovane e gentile.","es-g34-u13.s.1":"Oggi sono malato.","es-g34-u13.s.2":"La zuppa è calda.","es-g34-u13.s.3":"Il gioco è divertente.","es-g34-u13.s.4":"Il negozio è chiuso.","es-g34-u13.s.5":"Lucía è peruviana.","es-g34-u13.s.6":"Siamo a scuola.","es-g34-u13.s.7":"Il gelato è freddo.","es-g34-u13.g.title":"Distinguere ser e estar","es-g34-u13.g.x.0":"ser = com'è di solito (nome, lavoro, paese, carattere, ora): Soy alto. Es profesora. Son las dos.","es-g34-u13.g.x.1":"estar = come sta adesso, dove si trova, come si sente: Estoy enfermo. Está en casa. Están contentos.","es-g34-u13.g.x.2":"La stessa parola cambia significato: Es aburrido (è una persona noiosa) / Está aburrido (si sta annoiando adesso).","es-g34-u13.g.0":"Mio papà è medico.","es-g34-u13.g.1":"Oggi sono stanco.","es-g34-u13.g.2":"La porta è aperta.","es-g34-u13.g.3":"Siamo messicani.","es-g34-u13.g.4":"Il caffè è caldo.","es-g34-u13.g.5":"Lei è malata.","es-g34-u13.g.5.task":'Riscrivila con "enferma" (malata)',"es-g34-u13.g.6":"Il negozio è chiuso.","es-g34-u13.g.6.task":'Riscrivila con "cerrada" (chiusa)',"es-g34-u13.g.7":"I miei amici sono divertenti.","es-g34-u13.g.7.task":"Metti al plurale","es-g34-u14.title":"Dove vai? ir + a","es-g34-u14.tip":'"¿Adónde vas?" vuol dire "Dove vai?". La risposta comincia con Voy a…',"es-g34-u14.w.0":"andare","es-g34-u14.w.1":"cinema","es-g34-u14.w.2":"spiaggia","es-g34-u14.w.3":"supermercato","es-g34-u14.w.4":"museo","es-g34-u14.w.5":"stazione","es-g34-u14.w.6":"montagna","es-g34-u14.w.7":"ristorante","es-g34-u14.w.8":"zoo","es-g34-u14.w.9":"fine settimana","es-g34-u14.s.0":"Vado in spiaggia.","es-g34-u14.s.1":"Dove vai?","es-g34-u14.s.2":"Andiamo al cinema.","es-g34-u14.s.3":"La mamma va al supermercato.","es-g34-u14.s.4":"I miei amici vanno allo zoo.","es-g34-u14.s.5":"Nel fine settimana andiamo in montagna.","es-g34-u14.s.6":"Vado alla stazione in bicicletta.","es-g34-u14.s.7":"Vai al museo oggi?","es-g34-u14.g.title":"Il verbo ir e a / al","es-g34-u14.g.x.0":'"Andare" si dice ir: voy, vas, va, vamos, van. Cambia molto, quindi imparalo tutto a memoria.',"es-g34-u14.g.x.1":"Per dire dove vai si usa a: Voy a la playa.","es-g34-u14.g.x.2":"a + el si unisce in al: Voy al cine. (a el cine ✗)","es-g34-u14.g.0":"Vado a scuola.","es-g34-u14.g.1":"Vai al parco?","es-g34-u14.g.2":"Lei va al supermercato.","es-g34-u14.g.2.task":'Riscrivi la frase iniziando con "Ella"',"es-g34-u14.g.3":"Andiamo al cinema.","es-g34-u14.g.4":"Vado al museo.","es-g34-u14.g.5":"Vado in spiaggia.","es-g34-u14.g.6":"Andiamo allo zoo.","es-g34-u14.g.6.task":'Riscrivi la frase iniziando con "Nosotros"',"es-g34-u14.g.7":"Loro vanno in montagna.","es-g34-u14.g.7.task":'Riscrivi la frase iniziando con "Ellos"',"es-g34-u14.st.title":"Programmi per il fine settimana","es-g34-u14.st.l.0":"Elena, dove vai sabato?","es-g34-u14.st.l.1":"Vado allo zoo con la mia famiglia. E tu?","es-g34-u14.st.l.2":"Io vado in spiaggia. Fa caldo.","es-g34-u14.st.l.3":"Che bello! Domenica noi andiamo al cinema. Vieni?","es-g34-u14.st.l.4":"Sì, vengo con voi. A che ora?","es-g34-u14.st.l.5":"Alle cinque. Ci vediamo domenica!","es-g34-u14.st.q.0":"Dove va Carlos sabato?","es-g34-u14.st.q.0.o.0":"Allo zoo","es-g34-u14.st.q.0.o.1":"In spiaggia","es-g34-u14.st.q.0.o.2":"Al cinema","es-g34-u14.st.q.1":"A che ora è il film di domenica?","es-g34-u14.st.q.1.o.0":"Alle tre","es-g34-u14.st.q.1.o.1":"Alle quattro","es-g34-u14.st.q.1.o.2":"Alle cinque","es-g34-u15.title":"Che ore sono?","es-g34-u15.tip":"Guarda l'orologio e di' Son las… Ricorda: solo per l'una si dice Es la una!","es-g34-u15.w.0":"ora","es-g34-u15.w.1":"orologio","es-g34-u15.w.2":"minuto","es-g34-u15.w.3":"mezzogiorno","es-g34-u15.w.4":"mezzanotte","es-g34-u15.w.5":"presto","es-g34-u15.w.6":"tardi","es-g34-u15.w.7":"colazione","es-g34-u15.w.8":"cena","es-g34-u15.w.9":"ricreazione","es-g34-u15.s.0":"Che ore sono?","es-g34-u15.s.1":"È l'una.","es-g34-u15.s.2":"Sono le tre.","es-g34-u15.s.3":"Sono le cinque e mezza.","es-g34-u15.s.4":"Sono le otto e un quarto.","es-g34-u15.s.5":"La colazione è alle sette.","es-g34-u15.s.6":"La ricreazione è alle undici.","es-g34-u15.s.7":"Mi alzo presto.","es-g34-u15.g.title":"Dire l'ora: Es la una / Son las dos","es-g34-u15.g.x.0":"Solo per l'una si dice Es la una; dalle due in poi Son las dos, Son las tres…","es-g34-u15.g.x.1":"I minuti si aggiungono con y: Son las dos y diez (le 2 e 10). La mezza è y media, il quarto è y cuarto.","es-g34-u15.g.x.2":'"Alle…" si dice a las: La clase es a las nueve.',"es-g34-u15.g.0":"È l'una.","es-g34-u15.g.1":"Sono le quattro.","es-g34-u15.g.2":"Sono le sei e mezza.","es-g34-u15.g.3":"Sono le nove e un quarto.","es-g34-u15.g.4":"La cena è alle otto.","es-g34-u15.g.5":"Sono le dieci.","es-g34-u15.g.5.task":"Scrivi l'ora di un'ora dopo","es-g34-u15.g.6":"La ricreazione è alle undici.","es-g34-u15.g.6.task":'Riscrivila con "once" (le undici)',"es-g34-u15.g.7":"È l'una e mezza.","es-g34-u15.g.7.task":'Aggiungi "y media" (e mezza)',"es-g34-u16.title":"Questo, quello: este, ese, aquel","es-g34-u16.tip":"Indica con la mano. Se è nella tua mano, este; se è vicino al tuo amico, ese; se è lontano laggiù, aquel!","es-g34-u16.w.0":"questo","es-g34-u16.w.1":"codesto (quello lì)","es-g34-u16.w.2":"quello (laggiù)","es-g34-u16.w.3":"camicia","es-g34-u16.w.4":"gonna","es-g34-u16.w.5":"cappellino","es-g34-u16.w.6":"prezzo","es-g34-u16.w.7":"economico","es-g34-u16.w.8":"caro","es-g34-u16.w.9":"taglia","es-g34-u16.s.0":"Questo libro è mio.","es-g34-u16.s.1":"Quella camicia è bella.","es-g34-u16.s.2":"Quella montagna laggiù è alta.","es-g34-u16.s.3":"Quanto costa questo cappellino?","es-g34-u16.s.4":"Quell'orologio è molto caro.","es-g34-u16.s.5":"Queste scarpe sono economiche.","es-g34-u16.s.6":"Voglio quella gonna blu.","es-g34-u16.s.7":"Di che taglia è questo?","es-g34-u16.g.title":"I dimostrativi: este (questo), ese (quello lì), aquel (quello laggiù)","es-g34-u16.g.x.0":"Se è vicino, este; se è un po' lontano, ese; se è molto lontano, aquel.","es-g34-u16.g.x.1":"Si accordano con il nome: este libro / esta casa / estos libros / estas casas.","es-g34-u16.g.x.2":"ese → esa, esos, esas / aquel → aquella, aquellos, aquellas.","es-g34-u16.g.0":"Questo libro è nuovo.","es-g34-u16.g.1":"Questa camicia è bianca.","es-g34-u16.g.2":"Quel cane è grande.","es-g34-u16.g.3":"Quella casa laggiù è vecchia.","es-g34-u16.g.4":"Queste scarpe sono care.","es-g34-u16.g.5":"Quei cappellini sono economici.","es-g34-u16.g.5.task":"Metti al plurale","es-g34-u16.g.6":"Quella gonna è bella.","es-g34-u16.g.6.task":'Riscrivila con "esa" (quella)',"es-g34-u16.g.7":"Quell'albero laggiù è alto.","es-g34-u16.g.7.task":'Riscrivila con "aquel" (quello laggiù)',"es-g34-u17.title":"Voglio, posso: querer, poder","es-g34-u17.tip":'"¿Puedo…?" serve per chiedere il permesso. ¿Puedo entrar? ¿Puedo salir?',"es-g34-u17.w.0":"volere","es-g34-u17.w.1":"potere","es-g34-u17.w.2":"giocare","es-g34-u17.w.3":"dormire","es-g34-u17.w.4":"aiutare","es-g34-u17.w.5":"uscire","es-g34-u17.w.6":"entrare","es-g34-u17.w.7":"dipingere","es-g34-u17.w.8":"volare","es-g34-u17.w.9":"permesso","es-g34-u17.s.0":"Voglio giocare con te.","es-g34-u17.s.1":"Vuoi un gelato?","es-g34-u17.s.2":"Oggi non posso uscire.","es-g34-u17.s.3":"Posso entrare?","es-g34-u17.s.4":"Gli uccelli possono volare.","es-g34-u17.s.5":"Vogliamo dipingere la parete.","es-g34-u17.s.6":"Il mio fratellino vuole dormire.","es-g34-u17.s.7":"Puoi aiutare la mamma?","es-g34-u17.g.title":"querer (volere) e poder (potere) + infinito","es-g34-u17.g.x.0":"querer: quiero, quieres, quiere, queremos, quieren. La e diventa ie (tranne con nosotros).","es-g34-u17.g.x.1":"poder: puedo, puedes, puede, podemos, pueden. La o diventa ue (tranne con nosotros).","es-g34-u17.g.x.2":"Dopo si mette il verbo all'infinito: Quiero comer. Puedo nadar.","es-g34-u17.g.0":"Voglio giocare.","es-g34-u17.g.1":"Vuoi un gelato?","es-g34-u17.g.2":"Lei sa nuotare.","es-g34-u17.g.3":"Possiamo aiutare.","es-g34-u17.g.4":"Loro vogliono uscire.","es-g34-u17.g.5":"Oggi non posso uscire.","es-g34-u17.g.5.task":"Trasformala in una frase negativa (no)","es-g34-u17.g.6":"Puoi dipingere con me?","es-g34-u17.g.6.task":'Trasformala in una domanda con "¿Tú…?"',"es-g34-u17.g.7":"Vogliamo dormire.","es-g34-u17.g.7.task":'Riscrivi la frase iniziando con "Nosotros"',"es-g34-u17.st.title":"Posso uscire a giocare?","es-g34-u17.st.l.0":"Mamma, posso uscire a giocare?","es-g34-u17.st.l.1":"Vuoi giocare adesso? Prima i compiti.","es-g34-u17.st.l.2":"Ho finito i compiti. Posso aiutarti in cucina!","es-g34-u17.st.l.3":"Molto bene. Puoi uscire per un'ora.","es-g34-u17.st.l.4":"Grazie! Voglio giocare a calcio con Diego.","es-g34-u17.st.q.0":"Che cosa dice la mamma di fare prima?","es-g34-u17.st.q.0.o.0":"I compiti","es-g34-u17.st.q.0.o.1":"La cena","es-g34-u17.st.q.0.o.2":"Il riposino","es-g34-u17.st.q.1":"Per quanto tempo può uscire Hugo?","es-g34-u17.st.q.1.o.0":"Trenta minuti","es-g34-u17.st.q.1.o.1":"Un'ora","es-g34-u17.st.q.1.o.2":"Due ore","es-g34-u18.title":"Mesi, stagioni e date","es-g34-u18.tip":'Come in italiano, prima viene il numero: "5 de mayo". Prova a dire il tuo compleanno in spagnolo!',"es-g34-u18.w.0":"gennaio","es-g34-u18.w.1":"aprile","es-g34-u18.w.2":"luglio","es-g34-u18.w.3":"ottobre","es-g34-u18.w.4":"dicembre","es-g34-u18.w.5":"primavera","es-g34-u18.w.6":"estate","es-g34-u18.w.7":"autunno","es-g34-u18.w.8":"inverno","es-g34-u18.w.9":"vacanze","es-g34-u18.s.0":"Oggi è il 3 maggio.","es-g34-u18.s.1":"Il mio compleanno è a luglio.","es-g34-u18.s.2":"In inverno fa freddo.","es-g34-u18.s.3":"La primavera è bellissima.","es-g34-u18.s.4":"Che giorno è oggi?","es-g34-u18.s.5":"Le vacanze sono in estate.","es-g34-u18.s.6":"In autunno cadono le foglie.","es-g34-u18.s.7":"Dicembre è l'ultimo mese.","es-g34-u18.g.title":"Dire la data: el + numero + de + mese","es-g34-u18.g.x.0":"Nella data prima viene il numero, poi il mese: Hoy es cinco de abril. (5 aprile)","es-g34-u18.g.x.1":"Solo il primo del mese è el primero: el primero de enero.","es-g34-u18.g.x.2":'Mesi e stagioni si scrivono con la minuscola. "A/in" un mese si dice en: en julio, en verano.',"es-g34-u18.g.0":"Oggi è il 2 marzo.","es-g34-u18.g.1":"Il mio compleanno è il 10 luglio.","es-g34-u18.g.2":"Oggi è il primo gennaio.","es-g34-u18.g.3":"In estate fa caldo.","es-g34-u18.g.4":"Le lezioni cominciano a settembre.","es-g34-u18.g.5":"Oggi è il 5 aprile.","es-g34-u18.g.5.task":"Scrivi la data del giorno dopo","es-g34-u18.g.6":"In inverno nevica.","es-g34-u18.g.6.task":'Riscrivila con "invierno … nieva"',"es-g34-u18.g.7":"Il mio compleanno è a dicembre.","es-g34-u18.g.7.task":'Riscrivila con "diciembre"',"es-g34-u19.title":"Sempre, a volte: la mia giornata","es-g34-u19.tip":"Racconta la tua giornata in spagnolo: Siempre…, normalmente…, a veces…, nunca….","es-g34-u19.w.0":"a volte","es-g34-u19.w.1":"di solito","es-g34-u19.w.2":"fare colazione","es-g34-u19.w.3":"pranzare","es-g34-u19.w.4":"cenare","es-g34-u19.w.5":"riposare","es-g34-u19.w.6":"arrivare","es-g34-u19.w.7":"guardare","es-g34-u19.w.8":"televisione","es-g34-u19.w.9":"routine","es-g34-u19.s.0":"Faccio sempre colazione alle sette.","es-g34-u19.s.1":"A volte pranzo a scuola.","es-g34-u19.s.2":"Di solito arrivo a casa alle quattro.","es-g34-u19.s.3":"Nel pomeriggio riposo un po'.","es-g34-u19.s.4":"La mattina non guardo mai la televisione.","es-g34-u19.s.5":"Ceniamo alle otto.","es-g34-u19.s.6":"Il sabato gioco con i miei cugini.","es-g34-u19.s.7":"La mia routine è semplice.","es-g34-u19.g.title":"Avverbi di frequenza: siempre, normalmente, a veces, nunca","es-g34-u19.g.x.0":"Quanto spesso: siempre (sempre) > normalmente (di solito) > a veces (a volte) > nunca (mai).","es-g34-u19.g.x.1":"Di solito vanno all'inizio della frase o davanti al verbo: Siempre desayuno. A veces como pizza.","es-g34-u19.g.x.2":'"Ogni lunedì, ogni sabato" si dice los + giorno: los lunes, los sábados. "La mattina" è por la mañana, "il pomeriggio" è por la tarde.',"es-g34-u19.g.0":"Faccio sempre colazione con la mia famiglia.","es-g34-u19.g.1":"A volte mangio a scuola.","es-g34-u19.g.2":"Non arrivo mai in ritardo.","es-g34-u19.g.2.task":'Riscrivila con "nunca" (mai)',"es-g34-u19.g.3":"Di solito ceno alle otto.","es-g34-u19.g.4":"Il lunedì ho lezione di musica.","es-g34-u19.g.5":"La mattina faccio colazione.","es-g34-u19.g.6":"Non guardo mai la televisione.","es-g34-u19.g.6.task":'Riscrivila con "nunca" (mai)',"es-g34-u19.g.7":"Il sabato riposo.","es-g34-u19.g.7.task":'Riscrivila con "ogni sabato" (los sábados)',"es-g34-u20.title":"E, ma, perché","es-g34-u20.tip":'Con pero e porque puoi fare frasi più lunghe. "Quiero…, pero…" / "… porque …"',"es-g34-u20.w.0":"ma","es-g34-u20.w.1":"perché (il motivo)","es-g34-u20.w.2":"anche","es-g34-u20.w.3":"allora (quindi)","es-g34-u20.w.4":"contento","es-g34-u20.w.5":"stanco","es-g34-u20.w.6":"difficile","es-g34-u20.w.7":"facile","es-g34-u20.w.8":"pioggia","es-g34-u20.w.9":"passeggiata","es-g34-u20.s.0":"Ho un cane e un gatto.","es-g34-u20.s.1":"Voglio uscire, ma piove.","es-g34-u20.s.2":"Non vado perché sono stanco.","es-g34-u20.s.3":"I compiti sono difficili, ma li finisco.","es-g34-u20.s.4":"Sono contento perché è venerdì.","es-g34-u20.s.5":"Piove, allora niente passeggiata.","es-g34-u20.s.6":"Mi piace leggere e anche disegnare.","es-g34-u20.s.7":"La verifica è facile e corta.","es-g34-u20.g.title":"Le congiunzioni y / pero / porque","es-g34-u20.g.x.0":"y (e) unisce due cose: pan y leche. Se la parola dopo comincia con i-, diventa e: padres e hijos.","es-g34-u20.g.x.1":"pero (ma) unisce cose opposte: Es pequeño, pero fuerte.","es-g34-u20.g.x.2":"porque (perché) spiega il motivo: No salgo porque llueve. Si scrive tutto attaccato, diverso dalla domanda ¿por qué?","es-g34-u20.g.0":"Ho pane e formaggio.","es-g34-u20.g.1":"È piccolo, ma forte.","es-g34-u20.g.2":"Non esco perché piove.","es-g34-u20.g.3":"Genitori e figli giocano insieme.","es-g34-u20.g.4":"Sono stanco, allora riposo.","es-g34-u20.g.5":"Voglio giocare, ma ho i compiti.","es-g34-u20.g.5.task":'Unisci in una frase sola con "pero"',"es-g34-u20.g.6":"Sono felice perché è sabato.","es-g34-u20.g.6.task":'Unisci in una frase sola con "porque"',"es-g34-u20.g.7":"Mi piace leggere e disegnare.","es-g34-u20.g.7.task":'Unisci in una frase sola con "y"'},i={"es-g56-u01.title":"Io faccio, io esco: i verbi irregolari","es-g56-u01.tip":'Con "io" finiscono in -go: hago, salgo, pongo, traigo, vengo, digo. Impara questi sei come una canzoncina.',"es-g56-u01.w.0":"fare","es-g56-u01.w.1":"uscire","es-g56-u01.w.2":"mettere","es-g56-u01.w.3":"portare","es-g56-u01.w.4":"venire","es-g56-u01.w.5":"dire","es-g56-u01.w.6":"conoscere (persone, luoghi)","es-g56-u01.w.7":"compiti","es-g56-u01.w.8":"zaino","es-g56-u01.w.9":"cortile","es-g56-u01.w.10":"merenda","es-g56-u01.w.11":"presto","es-g56-u01.s.0":"Faccio i compiti nel pomeriggio.","es-g56-u01.s.1":"Esco di casa alle otto.","es-g56-u01.s.2":"Metto lo zaino sulla sedia.","es-g56-u01.s.3":"Porto la merenda in cortile.","es-g56-u01.s.4":"Vieni a casa mia oggi?","es-g56-u01.s.5":"Dico sempre la verità.","es-g56-u01.s.6":"Conosco tutti i vicini.","es-g56-u01.s.7":"Mia sorella rifà il letto presto.","es-g56-u01.g.title":"Verbi con yo in -go: hago, salgo, pongo","es-g56-u01.g.x.0":'hacer, salir, poner, traer, venir, decir finiscono in -go solo con "io (yo)": hago, salgo, pongo, traigo, vengo, digo.',"es-g56-u01.g.x.1":"Le altre persone sono quasi regolari: haces, hace, hacemos, hacen / sales, sale, salimos, salen.","es-g56-u01.g.x.2":"venir e decir cambiano anche con tú e él: vienes, viene / dices, dice. conocer fa conozco.","es-g56-u01.g.0":"Faccio i compiti a casa.","es-g56-u01.g.1":"Esco alle tre.","es-g56-u01.g.2":"Apparecchio la tavola.","es-g56-u01.g.3":"Porto il pane.","es-g56-u01.g.4":"Tu vieni con me.","es-g56-u01.g.5":"Vengo da scuola.","es-g56-u01.g.5.task":'Riscrivi la frase iniziando con "Yo"',"es-g56-u01.g.6":"Dico la verità.","es-g56-u01.g.6.task":'Riscrivi la frase iniziando con "Yo"',"es-g56-u01.g.7":"Noi facciamo sport.","es-g56-u01.g.7.task":'Riscrivi la frase iniziando con "Nosotros"',"es-g56-u01.r.ko":"La giornata di Mateo","es-g56-u01.r.genre":"Racconto di vita quotidiana","es-g56-u01.r.p.0":"Mi chiamo Mateo e ho undici anni. Esco di casa alle otto meno un quarto. Metto i libri e la merenda nello zaino e saluto la nonna. La scuola è vicina, così vengo in bicicletta.","es-g56-u01.r.p.1":"Alla ricreazione esco in cortile con Lucía. Lei porta sempre la frutta e io porto i biscotti. Dopo le lezioni faccio i compiti in biblioteca. Conosco tutti i maestri, e anche loro conoscono me.","es-g56-u01.r.p.2":"La sera apparecchio la tavola e ceno con la mia famiglia. Papà dice che sono molto responsabile. Domani farò tutto uguale!","es-g56-u01.r.q.3.o.0":"merenda","es-g56-u01.r.q.3.o.1":"compiti","es-g56-u01.r.q.3.o.2":"bicicletta","es-g56-u01.r.q.3.o.3":"biblioteca","es-g56-u02.title":"e→ie, o→ue: i verbi che cambiano forma","es-g56-u02.tip":'Solo nosotros non cambia! "empezamos, volvemos" tengono la vocale originale.',"es-g56-u02.w.0":"cominciare","es-g56-u02.w.1":"pensare","es-g56-u02.w.2":"capire","es-g56-u02.w.3":"preferire","es-g56-u02.w.4":"tornare","es-g56-u02.w.5":"contare (raccontare)","es-g56-u02.w.6":"ricordare","es-g56-u02.w.7":"trovare","es-g56-u02.w.8":"pranzo","es-g56-u02.w.9":"chiave","es-g56-u02.w.10":"tasca","es-g56-u02.w.11":"lezione","es-g56-u02.s.0":"La lezione comincia alle nove.","es-g56-u02.s.1":"Penso ai miei nonni.","es-g56-u02.s.2":"Non capisco questa parola.","es-g56-u02.s.3":"Preferisco il pranzo di casa.","es-g56-u02.s.4":"Torno a casa alle cinque.","es-g56-u02.s.5":"Conto le monete nella tasca.","es-g56-u02.s.6":"Ricordi la lezione di ieri?","es-g56-u02.s.7":"Non trovo le mie chiavi.","es-g56-u02.g.title":"Verbi con cambio di vocale: e→ie, o→ue","es-g56-u02.g.x.0":"In alcuni verbi la vocale in mezzo cambia. e→ie: empiezo, piensas, entiende, prefieren.","es-g56-u02.g.x.1":"o→ue: vuelvo, cuentas, recuerda, encuentran.","es-g56-u02.g.x.2":"nosotros non cambia: empezamos, volvemos. Ricorda la forma a stivale (boot): solo nosotros resta fuori.","es-g56-u02.g.0":"Il film comincia adesso.","es-g56-u02.g.1":"Penso a te.","es-g56-u02.g.2":"Capisci la lezione?","es-g56-u02.g.3":"Torniamo tardi.","es-g56-u02.g.4":"Lui conta fino a dieci.","es-g56-u02.g.5":"Preferisco il tè.","es-g56-u02.g.5.task":'Riscrivi la frase iniziando con "Yo"',"es-g56-u02.g.6":"Loro tornano a casa.","es-g56-u02.g.6.task":'Riscrivi la frase iniziando con "Ellos"',"es-g56-u02.g.7":"Non ricordo il suo nome.","es-g56-u02.g.7.task":"Trasformala in una frase negativa (no)","es-g56-u03.title":"Mi alzo e mi lavo: i verbi riflessivi","es-g56-u03.tip":"Di' in ordine quello che fai la mattina: Me despierto, me levanto, me ducho, me visto, me peino.","es-g56-u03.w.0":"alzarsi","es-g56-u03.w.1":"farsi la doccia","es-g56-u03.w.2":"vestirsi","es-g56-u03.w.3":"pettinarsi","es-g56-u03.w.4":"lavarsi","es-g56-u03.w.5":"andare a letto","es-g56-u03.w.6":"svegliarsi","es-g56-u03.w.7":"sedersi","es-g56-u03.w.8":"spazzolino","es-g56-u03.w.9":"asciugamano","es-g56-u03.w.10":"specchio","es-g56-u03.w.11":"pigiama","es-g56-u03.s.0":"Mi alzo alle sette.","es-g56-u03.s.1":"Mi faccio la doccia e mi vesto in fretta.","es-g56-u03.s.2":"Mio fratello si pettina davanti allo specchio.","es-g56-u03.s.3":"Ci laviamo le mani prima di mangiare.","es-g56-u03.s.4":"Vado a letto alle nove e mezza.","es-g56-u03.s.5":"A che ora ti svegli?","es-g56-u03.s.6":"I bambini si siedono per terra.","es-g56-u03.s.7":"Mi asciugo con l'asciugamano blu.","es-g56-u03.g.title":"Verbi riflessivi: me levanto, te duchas, se viste","es-g56-u03.g.x.0":"Per le azioni che fai a te stesso metti davanti me, te, se, nos, se: Me levanto. Te duchas. Se viste.","es-g56-u03.g.x.1":"Se l'infinito finisce con -se, è un verbo riflessivo: levantarse, acostarse.","es-g56-u03.g.x.2":"Puoi anche attaccarlo dopo l'infinito: Quiero levantarme. Voy a ducharme.","es-g56-u03.g.0":"Mi alzo alle sette.","es-g56-u03.g.1":"Ti fai la doccia la mattina?","es-g56-u03.g.2":"Lei si veste da sola.","es-g56-u03.g.3":"Ci laviamo i denti.","es-g56-u03.g.4":"Loro vanno a letto tardi.","es-g56-u03.g.5":"Mi sveglio alle sei.","es-g56-u03.g.5.task":'Cambia la frase per "Yo"',"es-g56-u03.g.6":"Ci sediamo qui.","es-g56-u03.g.6.task":'Cambia la frase per "Nosotros"',"es-g56-u03.g.7":"Voglio andare a letto presto.","es-g56-u03.g.7.task":'Riscrivila con "Quiero + infinito"',"es-g56-u03.r.ko":"La mattina di Sofía","es-g56-u03.r.genre":"Racconto di vita quotidiana","es-g56-u03.r.p.0":"Sofía si sveglia alle sette meno dieci, ma non si alza fino alle sette. Prima si fa la doccia con l'acqua calda e si asciuga con un asciugamano giallo. Poi si veste. Oggi sceglie i pantaloni blu e una maglietta bianca.","es-g56-u03.r.p.1":'In bagno si lava i denti con lo spazzolino verde e si pettina davanti allo specchio. Il suo fratellino Hugo è ancora in pigiama. "Sbrigati, Hugo!" dice Sofía. Hugo si siede sul letto e sbadiglia.',"es-g56-u03.r.p.2":"Alle otto tutti e due fanno colazione con la mamma. La sera Sofía va a letto alle nove e mezza. Prima di dormire legge sempre un po'.","es-g56-u03.r.q.4.o.0":"sbadigliare","es-g56-u03.r.q.4.o.1":"cantare","es-g56-u03.r.q.4.o.2":"correre","es-g56-u03.r.q.4.o.3":"ridere","es-g56-u04.title":"Sto per…: ir a + infinito","es-g56-u04.tip":"I tuoi programmi per il fine settimana in spagnolo: Voy a…, Vamos a…. Se non hai programmi, No voy a hacer nada!","es-g56-u04.w.0":"viaggiare","es-g56-u04.w.1":"visitare","es-g56-u04.w.2":"comprare","es-g56-u04.w.3":"imparare","es-g56-u04.w.4":"nuotare","es-g56-u04.w.5":"valigia","es-g56-u04.w.6":"biglietto","es-g56-u04.w.7":"aeroporto","es-g56-u04.w.8":"albergo","es-g56-u04.w.9":"mappa","es-g56-u04.w.10":"prossimo","es-g56-u04.w.11":"presto (tra poco)","es-g56-u04.s.0":"Farò un viaggio in Messico.","es-g56-u04.s.1":"Andremo a trovare i nonni.","es-g56-u04.s.2":"Comprerai i biglietti?","es-g56-u04.s.3":"Mia sorella imparerà lo spagnolo.","es-g56-u04.s.4":"La prossima estate nuoteremo tanto.","es-g56-u04.s.5":"I miei genitori faranno le valigie.","es-g56-u04.s.6":"Arriveremo presto all'aeroporto.","es-g56-u04.s.7":"Non guarderò la mappa.","es-g56-u04.g.title":"ir a + infinito: il futuro vicino","es-g56-u04.g.x.0":'"Sto per… / farò…" si dice con ir + a + infinito: Voy a comer. Vas a leer. Va a dormir.',"es-g56-u04.g.x.1":"Al plurale Vamos a…, Van a…. Il negativo è No voy a….","es-g56-u04.g.x.2":"Si usa insieme alle parole di tempo: mañana (domani), el próximo año (l'anno prossimo), pronto (presto), esta noche (stanotte).","es-g56-u04.g.0":"Comprerò il pane.","es-g56-u04.g.1":"Viaggerai in estate?","es-g56-u04.g.2":"Lei visiterà il museo.","es-g56-u04.g.3":"Noi nuoteremo.","es-g56-u04.g.4":"Loro arriveranno presto.","es-g56-u04.g.5":"Domani imparerò a nuotare.","es-g56-u04.g.5.task":'Riscrivila con "Mañana voy a…"',"es-g56-u04.g.6":"Non comprerò il biglietto.","es-g56-u04.g.6.task":"Trasformala in una frase negativa (no)","es-g56-u04.g.7":"Andremo a trovare i nonni.","es-g56-u04.g.7.task":'Riscrivila al futuro con "Vamos a…"',"es-g56-u04.r.ko":"Il viaggio della famiglia Ruiz","es-g56-u04.r.genre":"Racconto di vita quotidiana","es-g56-u04.r.p.0":"La famiglia Ruiz il mese prossimo farà un viaggio in Perù. Il papà ha già i biglietti dell'aereo e la mamma stanotte prenoterà l'albergo. Diego, che ha dodici anni, è felicissimo perché vedrà Machu Picchu.","es-g56-u04.r.p.1":'La sua sorellina Carla comprerà una mappa e una macchina fotografica nuova. "Farò mille foto", dice Carla. Diego imparerà dieci parole in quechua prima del viaggio. Tutti e due faranno le valigie venerdì.',"es-g56-u04.r.p.2":`Sabato partiranno prestissimo per l'aeroporto. "Non arriveremo in ritardo", dice il papà. "E non dimenticheremo i passaporti!"`,"es-g56-u04.r.q.3.o.0":"prenotare","es-g56-u04.r.q.3.o.1":"comprare","es-g56-u04.r.q.3.o.2":"dimenticare","es-g56-u04.r.q.3.o.3":"scattare","es-g56-u05.title":"Ieri ho…: il passato dei verbi in -ar","es-g56-u05.tip":"Al passato yo è -é, él è -ó. Senza accento cambia il significato: canto (io canto) / cantó (lui ha cantato).","es-g56-u05.w.0":"ieri","es-g56-u05.w.1":"ieri sera","es-g56-u05.w.2":"scorso","es-g56-u05.w.3":"vincere","es-g56-u05.w.4":"ballare","es-g56-u05.w.5":"cantare","es-g56-u05.w.6":"cucinare","es-g56-u05.w.7":"pulire","es-g56-u05.w.8":"partita","es-g56-u05.w.9":"squadra","es-g56-u05.w.10":"gita","es-g56-u05.w.11":"compleanno","es-g56-u05.s.0":"Ieri ho giocato a calcio con la squadra.","es-g56-u05.s.1":"Ieri sera ho cenato con i nonni.","es-g56-u05.s.2":"Hai vinto la partita?","es-g56-u05.s.3":"Mia sorella ha ballato alla festa.","es-g56-u05.s.4":"Abbiamo cantato al compleanno di Lucía.","es-g56-u05.s.5":"I miei genitori hanno cucinato la paella.","es-g56-u05.s.6":"Sabato scorso ho pulito la mia camera.","es-g56-u05.s.7":"La gita è finita alle cinque.","es-g56-u05.g.title":"Passato dei verbi in -ar: hablé, hablaste, habló","es-g56-u05.g.x.0":"Per le cose già finite si usa il passato (pretérito). Verbi in -ar: habl-é, habl-aste, habl-ó, habl-amos, habl-aron.","es-g56-u05.g.x.1":"yo è -é, él/ella è -ó. L'accento ci deve essere sempre: canté, cantó.","es-g56-u05.g.x.2":"nosotros è uguale al presente (hablamos). Parole come ayer, anoche ti dicono che è passato.","es-g56-u05.g.x.3":"jugar con yo si scrive jugué (si aggiunge una u per tenere il suono).","es-g56-u05.g.0":"Ieri ho cantato a lezione.","es-g56-u05.g.1":"Hai ballato ieri sera?","es-g56-u05.g.2":"Mio papà ha cucinato la cena.","es-g56-u05.g.3":"Ieri abbiamo pulito la casa.","es-g56-u05.g.4":"Loro hanno vinto la partita.","es-g56-u05.g.5":"Ieri ho giocato a calcio.","es-g56-u05.g.5.task":'Mettila al passato aggiungendo "Ayer"',"es-g56-u05.g.6":"Lei ha parlato con la maestra.","es-g56-u05.g.6.task":"Mettila al passato","es-g56-u05.g.7":"L'anno scorso abbiamo viaggiato in treno.","es-g56-u05.g.7.task":'Riscrivi la frase iniziando con "Nosotros"',"es-g56-u06.title":"Ho mangiato, ho vissuto: il passato dei verbi in -er/-ir","es-g56-u06.tip":"Il passato di -er e -ir è esattamente uguale. comí/viví, comiste/viviste… basta imparare una serie sola!","es-g56-u06.w.0":"perdere","es-g56-u06.w.1":"rompere","es-g56-u06.w.2":"imparare","es-g56-u06.w.3":"correre","es-g56-u06.w.4":"aprire","es-g56-u06.w.5":"ricevere","es-g56-u06.w.6":"scrivere","es-g56-u06.w.7":"salire","es-g56-u06.w.8":"scale","es-g56-u06.w.9":"premio","es-g56-u06.w.10":"gara (concorso)","es-g56-u06.w.11":"sorpresa","es-g56-u06.s.0":"Ieri ho perso il berretto al parco.","es-g56-u06.s.1":"Il mio fratellino ha rotto un bicchiere.","es-g56-u06.s.2":"Abbiamo imparato una canzone nuova.","es-g56-u06.s.3":"Hai corso nella gara?","es-g56-u06.s.4":"Ho aperto la porta e ho visto la sorpresa.","es-g56-u06.s.5":"Lucía ha ricevuto un premio al concorso.","es-g56-u06.s.6":"Ho scritto una lettera al nonno.","es-g56-u06.s.7":"Siamo saliti di corsa per le scale.","es-g56-u06.g.title":"Passato dei verbi in -er / -ir: comí, comiste, comió","es-g56-u06.g.x.0":"Il passato dei verbi in -er e -ir è identico: com-í, com-iste, com-ió, com-imos, com-ieron.","es-g56-u06.g.x.1":"viv-í, viv-iste, viv-ió, viv-imos, viv-ieron.","es-g56-u06.g.x.2":"yo è -í, él/ella è -ió. Non dimenticare l'accento: perdí, perdió.","es-g56-u06.g.0":"Ieri ho mangiato la paella.","es-g56-u06.g.1":"Hai perso le chiavi?","es-g56-u06.g.2":"Lui ha rotto la finestra.","es-g56-u06.g.3":"Abbiamo imparato tanto.","es-g56-u06.g.4":"Loro hanno aperto il regalo.","es-g56-u06.g.5":"Lei ha ricevuto un premio.","es-g56-u06.g.5.task":"Mettila al passato","es-g56-u06.g.6":"Ho scritto una lettera.","es-g56-u06.g.6.task":"Mettila al passato","es-g56-u06.g.7":"Ieri siamo saliti sulla montagna.","es-g56-u06.g.7.task":'Riscrivi la frase iniziando con "Nosotros"',"es-g56-u06.r.ko":"Il concorso di disegno","es-g56-u06.r.genre":"Racconto","es-g56-u06.r.p.0":"Lunedì scorso a scuola hanno organizzato un concorso di disegno. Lucía ha disegnato un drago verde con grandi ali. Pablo ha disegnato il suo cane Toby, ma per sbaglio ha rotto la matita rossa e ha chiesto alla maestra un'altra matita.","es-g56-u06.r.p.1":'Alla fine del pomeriggio il preside ha aperto una busta e ha letto un nome. "Il primo premio va a… Lucía!" Lucía ha ricevuto una scatola di matite colorate e un libro. Pablo non ha vinto, ma ha imparato una cosa importante: disegnare con attenzione.',"es-g56-u06.r.p.2":`Quella sera Lucía ha scritto una lettera alla nonna: "Nonna, ho vinto il concorso. Che bella sorpresa!" E Pablo ha deciso di disegnare un drago per l'anno prossimo.`,"es-g56-u07.title":"Mangia! Apri!: l'imperativo","es-g56-u07.tip":"L'imperativo è corto e deciso! Provalo a casa: ¡Ven! ¡Mira! ¡Escucha! (con por favor dopo è ancora meglio)","es-g56-u07.w.0":"ascoltare","es-g56-u07.w.1":"guardare","es-g56-u07.w.2":"aspettare","es-g56-u07.w.3":"chiudere","es-g56-u07.w.4":"prendere (bere)","es-g56-u07.w.5":"passare (porgere)","es-g56-u07.w.6":"attenzione","es-g56-u07.w.7":"silenzio","es-g56-u07.w.8":"piano (lentamente)","es-g56-u07.w.9":"sale","es-g56-u07.w.10":"ricetta","es-g56-u07.w.11":"istruzioni","es-g56-u07.s.0":"Ascolta la maestra.","es-g56-u07.s.1":"Guarda la mappa, per favore.","es-g56-u07.s.2":"Aspetta un momento.","es-g56-u07.s.3":"Chiudi la finestra, fa freddo.","es-g56-u07.s.4":"Bevi un bicchiere d'acqua.","es-g56-u07.s.5":"Passami il sale, per favore.","es-g56-u07.s.6":"Parla piano e con attenzione.","es-g56-u07.s.7":"Leggi la ricetta prima di cucinare.","es-g56-u07.g.title":"Imperativo affermativo con tú: ¡Habla! ¡Come! ¡Abre!","es-g56-u07.g.x.0":'Per dire "fai questo!" a un amico, usa la stessa forma del presente di él/ella: habla, come, abre, escucha, cierra.',"es-g56-u07.g.x.1":"Alcuni irregolari vanno imparati a memoria: ten (tieni), ven (vieni), pon (metti), sal (esci), haz (fai), di (di').","es-g56-u07.g.x.2":"Parole come me, la si attaccano dopo: Pásame la sal. Ciérrala.","es-g56-u07.g.0":"Ascolta la canzone!","es-g56-u07.g.1":"Mangia la frutta!","es-g56-u07.g.2":"Apri il libro!","es-g56-u07.g.3":"Vieni qui, per favore!","es-g56-u07.g.4":"Apparecchia la tavola!","es-g56-u07.g.5":"Chiudi la porta!","es-g56-u07.g.5.task":"Trasformala in un ordine (imperativo)","es-g56-u07.g.6":"Guarda la mappa!","es-g56-u07.g.6.task":"Trasformala in un ordine (imperativo)","es-g56-u07.g.7":"Fai i compiti adesso!","es-g56-u07.g.7.task":"Trasformala in un ordine (imperativo)","es-g56-u08.title":"Più grande, meno caro: fare paragoni","es-g56-u08.tip":"Confronta la tua famiglia e i tuoi amici: Mi papá es más alto que mi mamá. Soy tan rápido como mi amigo.","es-g56-u08.w.0":"più","es-g56-u08.w.1":"meno","es-g56-u08.w.2":"migliore","es-g56-u08.w.3":"peggiore","es-g56-u08.w.4":"maggiore (più grande di età)","es-g56-u08.w.5":"minore (più piccolo di età)","es-g56-u08.w.6":"largo","es-g56-u08.w.7":"stretto","es-g56-u08.w.8":"rumoroso","es-g56-u08.w.9":"tranquillo","es-g56-u08.w.10":"edificio","es-g56-u08.w.11":"abitante","es-g56-u08.s.0":"Madrid è più grande di Toledo.","es-g56-u08.s.1":"Il paese è meno rumoroso della città.","es-g56-u08.s.2":"Mio fratello è più grande di me.","es-g56-u08.s.3":"Questo libro è migliore di quello.","es-g56-u08.s.4":"La strada è stretta come un corridoio.","es-g56-u08.s.5":"Ho tante matite quante ne hai tu.","es-g56-u08.s.6":"L'edificio nuovo è più alto della chiesa.","es-g56-u08.s.7":"Il mio cuginetto corre più veloce di me.","es-g56-u08.g.title":"Comparativi: más … que, menos … que, tan … como","es-g56-u08.g.x.0":'"Più … di": más + aggettivo + que. Soy más alto que tú.',"es-g56-u08.g.x.1":'"Meno … di": menos + aggettivo + que. "Tanto … quanto": tan + aggettivo + como.',"es-g56-u08.g.x.2":"Comparativi speciali: bueno → mejor, malo → peor, grande (età) → mayor, pequeño (età) → menor.","es-g56-u08.g.0":"Il leone è più grande del gatto.","es-g56-u08.g.1":"Il treno è meno veloce dell'aereo.","es-g56-u08.g.2":"La mia casa è bella come la tua.","es-g56-u08.g.3":"Questo gelato è migliore di quello.","es-g56-u08.g.4":"Mia sorella è più grande di me.","es-g56-u08.g.5":"La città è più rumorosa del paese.","es-g56-u08.g.5.task":'Riscrivila con "La ciudad … ruidosa"',"es-g56-u08.g.6":"Oggi fa meno freddo di ieri.","es-g56-u08.g.6.task":'Riscrivila con "menos" (meno)',"es-g56-u08.g.7":"Sono alto come mio cugino.","es-g56-u08.g.7.task":'Riscrivila con "tan … como" (tanto… quanto)',"es-g56-u08.r.ko":"Due città, due cugini","es-g56-u08.r.genre":"Testo informativo","es-g56-u08.r.p.0":"Javier vive a Madrid e sua cugina Elena vive a Cuenca. Madrid è molto più grande di Cuenca: ha più di tre milioni di abitanti, mentre Cuenca non arriva a sessantamila. A Madrid ci sono edifici più alti, strade più larghe e molto più rumore.","es-g56-u08.r.p.1":"Cuenca è più tranquilla e più antica. Le strade sono così strette che a volte le macchine non passano. Elena dice che l'aria di Cuenca è migliore di quella di Madrid. Javier dice che Madrid è più divertente perché ha più musei e più parchi.","es-g56-u08.r.p.2":"I due cugini hanno la stessa età e sono amici come fratelli. D'estate Javier visita Cuenca e d'inverno Elena visita Madrid. Così tutti e due conoscono il meglio di ogni città.","es-g56-u08.r.q.3.o.0":"antico","es-g56-u08.r.q.3.o.1":"rumoroso","es-g56-u08.r.q.3.o.2":"largo","es-g56-u08.r.q.3.o.3":"nuovo","es-g56-u09.title":"Il più grande, il migliore: il superlativo","es-g56-u09.tip":"Di' i record del mondo in spagnolo: el más alto, el más rápido, el más grande del mundo.","es-g56-u09.w.0":"lungo","es-g56-u09.w.1":"corto","es-g56-u09.w.2":"profondo","es-g56-u09.w.3":"famoso","es-g56-u09.w.4":"antico","es-g56-u09.w.5":"moderno","es-g56-u09.w.6":"delizioso","es-g56-u09.w.7":"pericoloso","es-g56-u09.w.8":"mondo","es-g56-u09.w.9":"pianeta","es-g56-u09.w.10":"animale","es-g56-u09.w.11":"deserto","es-g56-u09.s.0":"Il Nilo è il fiume più lungo del mondo.","es-g56-u09.s.1":"Giove è il pianeta più grande.","es-g56-u09.s.2":"La balenottera azzurra è l'animale più pesante.","es-g56-u09.s.3":"È la pizza più deliziosa della città.","es-g56-u09.s.4":"Mia nonna è la persona più gentile che conosco.","es-g56-u09.s.5":"Questo è l'edificio più antico del paese.","es-g56-u09.s.6":"Il Sahara è il deserto più famoso.","es-g56-u09.s.7":"Questa è la strada meno pericolosa.","es-g56-u09.g.title":"Superlativo: el/la más … de","es-g56-u09.g.x.0":'"Il più …" è el/la/los/las + más + aggettivo: el río más largo, la casa más bonita.',"es-g56-u09.g.x.1":'"Di / tra" si dice de: el más alto de la clase (il più alto della classe).',"es-g56-u09.g.x.2":'"Il meno …" è menos. Forme speciali: el mejor (il migliore), el peor (il peggiore), el mayor (il più grande di età).',"es-g56-u09.g.0":"È il fiume più lungo del mondo.","es-g56-u09.g.1":"È la città più antica della Spagna.","es-g56-u09.g.2":"Lei è la giocatrice migliore della squadra.","es-g56-u09.g.3":"È l'animale più pericoloso del mare.","es-g56-u09.g.4":"Mio fratello è il più grande della famiglia.","es-g56-u09.g.5":"È la strada meno pericolosa.","es-g56-u09.g.5.task":'Riscrivila con "menos" (il meno)',"es-g56-u09.g.6":"È la montagna più alta del paese.","es-g56-u09.g.6.task":'Trasformala in superlativo: "la … más alta del país"',"es-g56-u09.g.7":"È la torta più deliziosa della festa.","es-g56-u09.g.7.task":'Trasformala in superlativo: "el … más delicioso de la fiesta"',"es-g56-u10.title":"Guardalo: lo, la, los, las","es-g56-u10.tip":"Scegli in base al genere e al numero della cosa: el libro → lo, la carta → la, los lápices → los, las gafas → las.","es-g56-u10.w.0":"cercare","es-g56-u10.w.1":"portare (con sé)","es-g56-u10.w.2":"usare","es-g56-u10.w.3":"conservare (tenere)","es-g56-u10.w.4":"prestare","es-g56-u10.w.5":"avere bisogno","es-g56-u10.w.6":"invitare","es-g56-u10.w.7":"computer","es-g56-u10.w.8":"macchina fotografica","es-g56-u10.w.9":"occhiali","es-g56-u10.w.10":"ombrello","es-g56-u10.w.11":"portafoglio","es-g56-u10.s.0":"Dov'è il mio portafoglio? Non lo trovo.","es-g56-u10.s.1":"Mi serve l'ombrello. Oggi lo porto.","es-g56-u10.s.2":"Gli occhiali? Li tengo nello zaino.","es-g56-u10.s.3":"Vengono i cugini. Li invito a cena.","es-g56-u10.s.4":"Mi presti la macchina fotografica? Mi serve.","es-g56-u10.s.5":"Il computer è vecchio, ma lo uso ogni giorno.","es-g56-u10.s.6":"Cerco le chiavi. Le vedi?","es-g56-u10.s.7":"Ti invito alla mia festa.","es-g56-u10.g.title":"Pronomi oggetto diretto: lo, la, los, las, me, te","es-g56-u10.g.x.0":'Per non ripetere la stessa parola, "lo/la" è lo (maschile) / la (femminile), al plurale los/las: ¿El libro? Lo leo. ¿La carta? La escribo.',"es-g56-u10.g.x.1":'"Mi" è me, "ti" è te: Te invito. Me buscas.',"es-g56-u10.g.x.2":"Il pronome va prima del verbo. Se c'è un infinito, si può attaccare dopo: Quiero comprarlo.","es-g56-u10.g.0":"Il libro? Lo leggo stasera.","es-g56-u10.g.1":"La lettera? La scrivo domani.","es-g56-u10.g.2":"Le matite? Le tengo qui.","es-g56-u10.g.3":"Gli occhiali? Mi servono.","es-g56-u10.g.4":"Ti invito a casa mia.","es-g56-u10.g.5":"L'ombrello? Lo porto io.","es-g56-u10.g.5.task":'Sostituisci "el paraguas" con lo',"es-g56-u10.g.6":"La macchina fotografica? La uso tanto.","es-g56-u10.g.6.task":'Sostituisci "la cámara" con la',"es-g56-u10.g.7":"I cugini? Li invito.","es-g56-u10.g.7.task":'Sostituisci "los primos" con los',"es-g56-u11.title":"Sto facendo: estar + -ando/-iendo","es-g56-u11.tip":"Guardati intorno e di': Mamá está cocinando. El perro está durmiendo. ¿Qué estás haciendo tú?","es-g56-u11.w.0":"adesso","es-g56-u11.w.1":"ancora","es-g56-u11.w.2":"preparare","es-g56-u11.w.3":"costruire","es-g56-u11.w.4":"dipingere","es-g56-u11.w.5":"suonare (toccare)","es-g56-u11.w.6":"ridere","es-g56-u11.w.7":"piangere","es-g56-u11.w.8":"fiera (festa di paese)","es-g56-u11.w.9":"chitarra","es-g56-u11.w.10":"pagliaccio","es-g56-u11.w.11":"palloncino","es-g56-u11.s.0":"Adesso sto facendo i compiti.","es-g56-u11.s.1":"Che cosa stai mangiando?","es-g56-u11.s.2":"La mamma sta preparando la cena.","es-g56-u11.s.3":"I bambini stanno costruendo un castello di sabbia.","es-g56-u11.s.4":"Mio fratello sta suonando la chitarra.","es-g56-u11.s.5":"Il pagliaccio sta ridendo con i bambini.","es-g56-u11.s.6":"Stiamo ancora dipingendo la parete.","es-g56-u11.s.7":"Il bebè sta piangendo perché ha perso il palloncino.","es-g56-u11.g.title":"Presente progressivo: estar + -ando / -iendo","es-g56-u11.g.x.0":'"Sto facendo…" è estar + il verbo in -ando (-ar) / -iendo (-er, -ir): Estoy hablando. Estás comiendo. Está escribiendo.',"es-g56-u11.g.x.1":"La i tra due vocali diventa y: leer → leyendo, construir → construyendo. dormir → durmiendo, reír → riendo.","es-g56-u11.g.x.2":"Solo estar cambia con la persona; -ando/-iendo resta uguale.","es-g56-u11.g.0":"Sto parlando con la mamma.","es-g56-u11.g.1":"Stai mangiando?","es-g56-u11.g.2":"Lei sta scrivendo una lettera.","es-g56-u11.g.3":"Stiamo leggendo un libro.","es-g56-u11.g.4":"Loro stanno costruendo una casa.","es-g56-u11.g.5":"Il mio fratellino sta dormendo.","es-g56-u11.g.5.task":"Trasformala in un'azione in corso (presente progressivo)","es-g56-u11.g.6":"Adesso sto dipingendo la porta.","es-g56-u11.g.6.task":'Trasformala al presente progressivo con "Ahora estoy…"',"es-g56-u11.g.7":"I bambini stanno ridendo.","es-g56-u11.g.7.task":"Trasformala in un'azione in corso (presente progressivo)","es-g56-u11.r.ko":"La fiera del paese","es-g56-u11.r.genre":"Testo descrittivo","es-g56-u11.r.p.0":'Sabato pomeriggio, la fiera del paese è piena di gente. In piazza un pagliaccio con il naso rosso sta facendo animali con i palloncini. I bambini ridono e gridano: "Un cagnolino! Una giraffa!"',"es-g56-u11.r.p.1":"Vicino alla fontana tre musicisti stanno suonando la chitarra e una signora sta cantando una canzone antica. Il nonno sta ballando con la nonna. La mamma sta preparando la cioccolata calda a una bancarella e il papà sta comprando i churros.","es-g56-u11.r.p.2":"Io sono seduto su una panchina con la mia sorellina. Lei sta disegnando sul suo quaderno quello che vede. Un bebè sta piangendo perché il suo palloncino è volato in cielo. Tutti stanno guardando quel palloncino!","es-g56-u11.r.q.3.o.0":"bancarella","es-g56-u11.r.q.3.o.1":"fontana","es-g56-u11.r.q.3.o.2":"panchina","es-g56-u11.r.q.3.o.3":"piazza","es-g56-u12.title":"Andai, feci, fui: il passato irregolare","es-g56-u12.tip":"Il passato di ir e ser è lo stesso: fui! Si capisce dal contesto: Fui al cine (andai) / Fui feliz (fui felice).","es-g56-u12.w.0":"nascere","es-g56-u12.w.1":"crescere","es-g56-u12.w.2":"inventare","es-g56-u12.w.3":"scoprire","es-g56-u12.w.4":"pittore","es-g56-u12.w.5":"scienziata","es-g56-u12.w.6":"secolo","es-g56-u12.w.7":"storia","es-g56-u12.w.8":"viaggio","es-g56-u12.w.9":"nave","es-g56-u12.w.10":"re","es-g56-u12.w.11":"quadro","es-g56-u12.s.0":"Ieri sono andato al museo con i compagni di classe.","es-g56-u12.s.1":"Picasso fu un pittore molto famoso.","es-g56-u12.s.2":"Marie Curie fece una scoperta importante.","es-g56-u12.s.3":"Colombo fece un lungo viaggio in nave.","es-g56-u12.s.4":"Mio nonno ebbe una vita felice.","es-g56-u12.s.5":"Dov'eri ieri?","es-g56-u12.s.6":"Quel re visse nel quindicesimo secolo.","es-g56-u12.s.7":"Siamo andati a vedere dei quadri antichi.","es-g56-u12.g.title":"Passato irregolare: fui, hice, tuve, estuve","es-g56-u12.g.x.0":"ir e ser hanno lo stesso passato: fui, fuiste, fue, fuimos, fueron. (andai / fui)","es-g56-u12.g.x.1":"hacer: hice, hiciste, hizo, hicimos, hicieron. tener: tuve, tuviste, tuvo, tuvimos, tuvieron.","es-g56-u12.g.x.2":"estar: estuve, estuviste, estuvo, estuvimos, estuvieron. Queste forme del passato non hanno accento.","es-g56-u12.g.0":"Ieri sono andato al parco.","es-g56-u12.g.1":"Picasso fu un grande pittore.","es-g56-u12.g.2":"Che cosa hai fatto domenica?","es-g56-u12.g.3":"Lei ha fatto una torta.","es-g56-u12.g.4":"Abbiamo avuto una verifica.","es-g56-u12.g.5":"Ieri sera sono stato a casa.","es-g56-u12.g.5.task":'Mettila al passato aggiungendo "anoche"',"es-g56-u12.g.6":"Loro sono andati in spiaggia.","es-g56-u12.g.6.task":"Mettila al passato","es-g56-u12.g.7":"Mia nonna ebbe cinque figli.","es-g56-u12.g.7.task":"Mettila al passato","es-g56-u12.r.ko":"Frida Kahlo, la pittrice dei colori","es-g56-u12.r.genre":"Biografia","es-g56-u12.r.p.0":"Frida Kahlo nacque in Messico nel 1907. Da piccola ebbe una malattia e qualche anno dopo ebbe un grave incidente in autobus. Rimase a letto per molti mesi. Suo padre le diede dei colori e uno specchio, e così Frida cominciò a dipingere.","es-g56-u12.r.p.1":"Frida dipinse molti autoritratti con fiori tra i capelli e colori molto forti. Dipinse anche gli animali che vivevano nella sua casa blu: scimmie, cani e pappagalli. Andò negli Stati Uniti e in Francia, e i suoi quadri diventarono famosi in tutto il mondo.","es-g56-u12.r.p.2":"Frida morì nel 1954, ma la sua casa blu oggi è un museo. Ogni anno migliaia di persone vanno a vedere i suoi quadri e il suo giardino.","es-g56-u12.r.q.4.o.0":"grave","es-g56-u12.r.q.4.o.1":"piccolo","es-g56-u12.r.q.4.o.2":"divertente","es-g56-u12.r.q.4.o.3":"blu","es-g56-u13.title":"Lo so: saber e conocer","es-g56-u13.tip":'"Saper fare" è sempre saber: Sé nadar. "Conoscere un posto, una persona" è conocer.',"es-g56-u13.w.0":"sapere (fatti, come si fa)","es-g56-u13.w.1":"conoscere (persone, luoghi)","es-g56-u13.w.2":"risposta","es-g56-u13.w.3":"indirizzo","es-g56-u13.w.4":"strada (via)","es-g56-u13.w.5":"lingua","es-g56-u13.w.6":"vicina di casa","es-g56-u13.w.7":"segreto","es-g56-u13.w.8":"numero","es-g56-u13.w.9":"andare in (bici)","es-g56-u13.w.10":"suonare","es-g56-u13.w.11":"capitale","es-g56-u13.s.0":"So nuotare e so andare in bicicletta.","es-g56-u13.s.1":"Sai la risposta?","es-g56-u13.s.2":"Conosco la tua vicina, è molto gentile.","es-g56-u13.s.3":"Non conosco ancora Barcellona.","es-g56-u13.s.4":"Mia zia sa tre lingue.","es-g56-u13.s.5":"Sai qual è la capitale del Perù?","es-g56-u13.s.6":"Non so il tuo numero di telefono.","es-g56-u13.s.7":"So un segreto, ma non lo dico.","es-g56-u13.g.title":"saber (fatti, come si fa) e conocer (persone, luoghi)","es-g56-u13.g.x.0":"Se sai un'informazione o come si fa qualcosa, saber: Sé la respuesta. Sé nadar. (sé, sabes, sabe, sabemos, saben)","es-g56-u13.g.x.1":"Se conosci una persona o un posto (ci sei stato), conocer: Conozco a Lucía. Conozco Madrid. (conozco, conoces, conoce…)","es-g56-u13.g.x.2":"Davanti a una persona si mette a: Conozco a tu hermano.","es-g56-u13.g.0":"So la risposta.","es-g56-u13.g.1":"Conosco il tuo maestro.","es-g56-u13.g.2":"Sai nuotare?","es-g56-u13.g.3":"Lei conosce Madrid molto bene.","es-g56-u13.g.4":"Sappiamo l'indirizzo.","es-g56-u13.g.5":"Conosco la tua vicina.","es-g56-u13.g.5.task":'Riscrivila con "a tu vecina" (una persona)',"es-g56-u13.g.6":"Non so suonare la chitarra.","es-g56-u13.g.6.task":"Trasformala in una frase negativa (no)","es-g56-u13.g.7":"Sai qual è la capitale?","es-g56-u13.g.7.task":'Trasformala in una domanda con "¿Tú…?"',"es-g56-u14.title":"Non farlo!: l'imperativo negativo","es-g56-u14.tip":"L'affermativo è habla/come, il negativo è no hables/no comas: ricorda che le vocali si scambiano.","es-g56-u14.w.0":"gridare","es-g56-u14.w.1":"toccare","es-g56-u14.w.2":"correre","es-g56-u14.w.3":"dimenticare","es-g56-u14.w.4":"disturbare","es-g56-u14.w.5":"buttare","es-g56-u14.w.6":"vietato","es-g56-u14.w.7":"regola","es-g56-u14.w.8":"corridoio","es-g56-u14.w.9":"spazzatura","es-g56-u14.w.10":"cestino","es-g56-u14.w.11":"cartello","es-g56-u14.s.0":"Non gridare in biblioteca.","es-g56-u14.s.1":"Non toccare i quadri, per favore.","es-g56-u14.s.2":"Non correre nel corridoio.","es-g56-u14.s.3":"Non dimenticare lo zaino.","es-g56-u14.s.4":"Non disturbare il cane mentre mangia.","es-g56-u14.s.5":"Non buttare la spazzatura per terra.","es-g56-u14.s.6":"È vietato mangiare in classe.","es-g56-u14.s.7":'Il cartello dice "Vietato entrare".',"es-g56-u14.g.title":"Imperativo negativo: No hables. No comas. No abras.","es-g56-u14.g.x.0":'"Non fare…" è no + una forma speciale: i verbi in -ar prendono -es, quelli in -er/-ir prendono -as. No hables. No comas. No abras.',"es-g56-u14.g.x.1":"Le vocali sono al contrario dell'affermativo: ¡Habla! ↔ No hables. ¡Come! ↔ No comas.","es-g56-u14.g.x.2":"A volte cambia la scrittura per tenere il suono: tocar → No toques. jugar → No juegues.","es-g56-u14.g.0":"Non gridare, per favore.","es-g56-u14.g.1":"Non mangiare in classe.","es-g56-u14.g.2":"Non aprire la finestra.","es-g56-u14.g.3":"Non toccare quello.","es-g56-u14.g.4":"Non giocare con il fuoco.","es-g56-u14.g.5":"Non correre nel corridoio.","es-g56-u14.g.5.task":"Trasformala in un divieto (imperativo negativo)","es-g56-u14.g.6":"Non dimenticare l'ombrello.","es-g56-u14.g.6.task":"Trasformala in un divieto (imperativo negativo)","es-g56-u14.g.7":"Non buttare carte per terra.","es-g56-u14.g.7.task":"Trasformala in un divieto (imperativo negativo)","es-g56-u15.title":"por e para","es-g56-u15.tip":'para guarda avanti (scopo, obiettivo), por guarda indietro (motivo). "Es para ti" / "Gracias por venir".',"es-g56-u15.w.0":"regalo","es-g56-u15.w.1":"motivo","es-g56-u15.w.2":"obiettivo","es-g56-u15.w.3":"finestra","es-g56-u15.w.4":"posta (e-mail)","es-g56-u15.w.5":"pomeriggio","es-g56-u15.w.6":"settimana","es-g56-u15.w.7":"prezzo","es-g56-u15.w.8":"euro","es-g56-u15.w.9":"treno","es-g56-u15.w.10":"bosco","es-g56-u15.w.11":"mattina (domani)","es-g56-u15.s.0":"Questo regalo è per te.","es-g56-u15.s.1":"Studio spagnolo per viaggiare in Messico.","es-g56-u15.s.2":"Grazie per l'aiuto.","es-g56-u15.s.3":"Camminiamo attraverso il bosco.","es-g56-u15.s.4":"Ho comprato il libro per 10 euro.","es-g56-u15.s.5":"Nel pomeriggio gioco a calcio.","es-g56-u15.s.6":"I compiti sono per lunedì.","es-g56-u15.s.7":"Mando la lettera per posta.","es-g56-u15.g.title":"por (motivo, passaggio, prezzo) e para (scopo, destinatario, scadenza)","es-g56-u15.g.x.0":'para = "per (qualcuno), per (fare), entro": Es para ti. Estudio para aprender. Es para el lunes.',"es-g56-u15.g.x.1":'por = "a causa di, attraverso, per (un prezzo)": Gracias por todo. Paso por el parque. Lo compré por dos euros.',"es-g56-u15.g.x.2":"Per i momenti della giornata si usa por: por la mañana, por la tarde, por la noche.","es-g56-u15.g.0":"Questo regalo è per la nonna.","es-g56-u15.g.1":"Grazie per il regalo.","es-g56-u15.g.2":"Studio per diventare medico.","es-g56-u15.g.3":"Camminiamo lungo la spiaggia.","es-g56-u15.g.4":"La mattina faccio colazione.","es-g56-u15.g.5":"I compiti sono per domani.","es-g56-u15.g.5.task":"Correggi il por sbagliato con la parola giusta","es-g56-u15.g.6":"L'ho comprato per 5 euro.","es-g56-u15.g.6.task":"Correggi il para sbagliato con la parola giusta","es-g56-u15.g.7":"Viaggio per vedere i miei cugini.","es-g56-u15.g.7.task":"Correggi il por sbagliato con la parola giusta","es-g56-u16.title":"Prima, poi, infine: raccontare una storia","es-g56-u16.tip":"Racconta la tua storia preferita in tre frasi con primero, luego, finalmente.","es-g56-u16.w.0":"prima","es-g56-u16.w.1":"poi","es-g56-u16.w.2":"dopo","es-g56-u16.w.3":"infine","es-g56-u16.w.4":"mentre","es-g56-u16.w.5":"all'improvviso","es-g56-u16.w.6":"volpe","es-g56-u16.w.7":"corvo","es-g56-u16.w.8":"formaggio","es-g56-u16.w.9":"ramo","es-g56-u16.w.10":"becco","es-g56-u16.w.11":"morale","es-g56-u16.s.0":"Prima, il corvo trovò un pezzo di formaggio.","es-g56-u16.s.1":"Poi si posò su un ramo alto.","es-g56-u16.s.2":"All'improvviso arrivò una volpe.","es-g56-u16.s.3":"Mentre parlava, la volpe guardava il formaggio.","es-g56-u16.s.4":"Il corvo aprì il becco per cantare.","es-g56-u16.s.5":"Il formaggio cadde a terra.","es-g56-u16.s.6":"Infine, la volpe mangiò il formaggio.","es-g56-u16.s.7":"La morale è: non credere a tutte le belle parole.","es-g56-u16.g.title":"Connettivi del racconto: primero, luego, después, finalmente, mientras, de repente","es-g56-u16.g.x.0":"Per dire l'ordine: primero (prima) → luego/después (poi) → finalmente (infine).","es-g56-u16.g.x.1":`mientras è "mentre", de repente è "all'improvviso". Rendono la storia più viva.`,"es-g56-u16.g.x.2":"I connettivi di solito vanno all'inizio della frase, con la virgola: Primero, … Luego, … Finalmente, ….","es-g56-u16.g.0":"Prima, mi alzo presto.","es-g56-u16.g.1":"Poi, faccio colazione con la famiglia.","es-g56-u16.g.2":"Infine, parto per la scuola.","es-g56-u16.g.3":"Canto mentre mi faccio la doccia.","es-g56-u16.g.4":"All'improvviso cominciò a piovere.","es-g56-u16.g.5":"Dopo cena leggo una storia.","es-g56-u16.g.5.task":'Riscrivila con "después de" (dopo)',"es-g56-u16.g.6":"Prima, la volpe vide il formaggio.","es-g56-u16.g.6.task":`Aggiungi "Primero," all'inizio`,"es-g56-u16.g.7":"Infine, il corvo perse il formaggio.","es-g56-u16.g.7.task":`Aggiungi "Finalmente," all'inizio`,"es-g56-u16.r.ko":"La volpe e il corvo","es-g56-u16.r.genre":"Favola","es-g56-u16.r.p.0":"Una mattina un corvo trovò un pezzo di formaggio sulla finestra di una casa. Lo prese con il becco e volò sul ramo più alto di un albero. Era molto contento e pensava di mangiarlo con calma.","es-g56-u16.r.p.1":`All'improvviso passò di lì una volpe e vide il formaggio. "Buongiorno, signor Corvo", disse la volpe. "Che piume bellissime! Sicuramente anche la sua voce è la più bella del bosco. Canterebbe per me?" Mentre parlava, la volpe non toglieva gli occhi dal formaggio.`,"es-g56-u16.r.p.2":"Il corvo, tutto orgoglioso, aprì il becco per cantare… e il formaggio cadde a terra. Infine la volpe lo prese e scappò via. Morale: non credere a tutte le parole dolci.","es-g56-u16.r.q.4.o.0":"orgoglioso (pieno di sé)","es-g56-u16.r.q.4.o.1":"affamato","es-g56-u16.r.q.4.o.2":"triste","es-g56-u16.r.q.4.o.3":"assonnato"},g={...e,...a,...s,...o,...i};export{g as default};
